# =============================================================================
# SECTION 2 — TIINGO PRICE PULL
# =============================================================================

print("SECTION 2 — Pulling Prices from Tiingo")
print("─" * 70)

def fetch_tiingo(ticker, start, end, api_key):
    url  = (f"https://api.tiingo.com/tiingo/daily/{ticker}/prices"
            f"?startDate={start}&endDate={end}&token={api_key}&resampleFreq=daily")
    resp = requests.get(url, headers={"Content-Type": "application/json"}, timeout=30)
    if resp.status_code != 200:
        raise RuntimeError(f"Tiingo {ticker}: HTTP {resp.status_code}")
    data = resp.json()
    if not data:
        raise ValueError(f"Empty data for {ticker}")
    df = pd.DataFrame(data)
    df["date"] = pd.to_datetime(df["date"]).dt.tz_localize(None)
    return df.set_index("date")[["adjClose"]].rename(columns={"adjClose": ticker})

# ── Smart pull: load from disk if already saved, else pull from Tiingo ────────
# Avoids HTTP 429 rate-limit errors on repeated runs.
# To force a fresh pull, delete data/prices_raw.csv manually.
if os.path.exists("data/prices_raw.csv"):
    print("  ⚡  data/prices_raw.csv found — loading from disk (skipping Tiingo).")
    print("     To force a fresh API pull, delete data/prices_raw.csv and rerun.")
    prices = pd.read_csv("data/prices_raw.csv", index_col=0, parse_dates=True)
    print(f"  ✓  Loaded  {prices.shape[0]} rows × {prices.shape[1]} cols")
    print(f"  Date range : {prices.index[0].date()} → {prices.index[-1].date()}")
else:
    print("  No cached data found — pulling from Tiingo API …")
    price_frames, pull_errors = [], []
    for ticker in ALL_TICKERS:
        try:
            df = fetch_tiingo(ticker, START_DATE, END_DATE, TIINGO_API_KEY)
            price_frames.append(df)
            print(f"  ✓  {ticker:6s}  |  {len(df):4d} rows  |  "
                  f"{df.index[0].date()} → {df.index[-1].date()}")
        except Exception as e:
            pull_errors.append(ticker)
            print(f"  ✗  {ticker:6s}  |  ERROR: {e}")
    if pull_errors:
        raise RuntimeError(
            f"Failed to pull: {pull_errors}.\n"
            "Check TIINGO_API_KEY or wait a few minutes if you hit a 429 rate limit."
        )
    prices = pd.concat(price_frames, axis=1).sort_index().ffill().dropna(how="all")
    print(f"\n  Price matrix : {prices.shape[0]} rows × {prices.shape[1]} cols")
    print(f"  Date range   : {prices.index[0].date()} → {prices.index[-1].date()}")
    prices.to_csv("data/prices_raw.csv")
    print("  Saved → data/prices_raw.csv")
print()

# =============================================================================
# SECTION 3 — DATA QUALITY CHECKS
# =============================================================================

print("SECTION 3 — Data Quality Checks")
print("─" * 70)

raw_returns  = np.log(prices / prices.shift(1)).dropna()
quality_rows = []

for ticker in ALL_TICKERS:
    col           = raw_returns[ticker]
    missing_count = int(col.isna().sum())
    outlier_mask  = np.abs(col) > (OUTLIER_SIGMA * col.rolling(63).std())
    outlier_count = int(outlier_mask.sum())
    zero_count    = int((col == 0).sum())
    quality_rows.append({
        "ticker": ticker, "total_rows": len(col),
        "missing_count": missing_count, "missing_pct": round(missing_count/len(col)*100, 3),
        "outlier_count": outlier_count, "outlier_pct": round(outlier_count/len(col)*100, 3),
        "zero_return_count": zero_count,
    })

quality_df = pd.DataFrame(quality_rows).set_index("ticker")
quality_df.to_csv("data/data_quality_report.csv")
print(quality_df[["missing_count","missing_pct","outlier_count","outlier_pct","zero_return_count"]].to_string())
print()

total_missing  = int(quality_df["missing_count"].sum())
total_outliers = int(quality_df["outlier_count"].sum())
print(f"  ✓  No missing values." if total_missing == 0 else f"  ⚠  {total_missing} missing values.")
print(f"  ⚠  {total_outliers} outlier days flagged (|r| > {OUTLIER_SIGMA}σ) — RETAINED (real market events).")
print("  Saved → data/data_quality_report.csv")
print()

# =============================================================================
# SECTION 4 — RETURN COMPUTATION
# =============================================================================

print("SECTION 4 — Return Computation")
print("─" * 70)

daily_log_returns = np.log(prices / prices.shift(1)).dropna()
monthly_returns   = ((1 + prices.pct_change()).resample("ME").prod() - 1).dropna()
portfolio_daily   = daily_log_returns.dot(WEIGHTS)
portfolio_monthly = monthly_returns.dot(WEIGHTS)
cum_ret           = (1 + portfolio_daily).cumprod()
roll_max          = cum_ret.cummax()
drawdown          = (cum_ret - roll_max) / roll_max

print(f"  Daily log returns  : {daily_log_returns.shape}")
print(f"  Monthly returns    : {monthly_returns.shape}")
print(f"  Max drawdown       : {drawdown.min()*100:.2f}%  on {drawdown.idxmin().date()}")
print(f"  Best single day    : {portfolio_daily.max()*100:.3f}%  on {portfolio_daily.idxmax().date()}")
print(f"  Worst single day   : {portfolio_daily.min()*100:.3f}%  on {portfolio_daily.idxmin().date()}")
print()

daily_log_returns.to_csv("data/daily_log_returns.csv")
monthly_returns.to_csv("data/monthly_returns.csv")
portfolio_daily.to_csv("data/portfolio_daily_returns.csv",    header=["portfolio_return"])
portfolio_monthly.to_csv("data/portfolio_monthly_returns.csv", header=["portfolio_return"])
drawdown.to_csv("data/portfolio_drawdown.csv", header=["drawdown"])
print("  Saved → data/daily_log_returns.csv, monthly_returns.csv, portfolio files, drawdown")
print()

# =============================================================================
# SECTION 5 — RETURN DISTRIBUTION DIAGNOSTICS
# =============================================================================

print("SECTION 5 — Return Distribution Diagnostics")
print("─" * 70)

diag_rows = []
for ticker in ALL_TICKERS:
    col = daily_log_returns[ticker].dropna()
    jb_stat, jb_pval = stats.jarque_bera(col)
    diag_rows.append({
        "ticker": ticker, "mean_daily": round(col.mean(),6), "std_daily": round(col.std(),6),
        "skewness": round(stats.skew(col),4), "excess_kurtosis": round(stats.kurtosis(col),4),
        "min_return": round(col.min(),6), "max_return": round(col.max(),6),
        "JB_stat": round(jb_stat,3), "JB_pvalue": round(jb_pval,6), "is_normal": jb_pval > 0.05,
    })

diag_df = pd.DataFrame(diag_rows).set_index("ticker")
diag_df.to_csv("data/return_diagnostics.csv")
print(diag_df[["mean_daily","std_daily","skewness","excess_kurtosis","JB_pvalue","is_normal"]].to_string())
print()
n_normal    = int(diag_df["is_normal"].sum())
n_nonnormal = len(diag_df) - n_normal
print(f"  {n_nonnormal}/{len(diag_df)} assets reject normality → Justifies HS-VaR and MC over Parametric.")
print("  Saved → data/return_diagnostics.csv")
print()

# =============================================================================
# SECTION 6 — FRED MACRO PULL + ADF STATIONARITY
# =============================================================================

print("SECTION 6 — FRED Macro Data Pull & Stationarity Tests")
print("─" * 70)

fred         = Fred(api_key=FRED_API_KEY)
macro_frames = {}
for series_id, label in FRED_SERIES.items():
    try:
        s = fred.get_series(series_id, observation_start=START_DATE, observation_end=END_DATE)
        s.name = series_id
        macro_frames[series_id] = s
        print(f"  ✓  {series_id:20s}  |  {label:35s}  |  {len(s):4d} obs")
    except Exception as e:
        print(f"  ✗  {series_id:20s}  |  ERROR: {e}")

macro_df = pd.DataFrame(macro_frames).sort_index().ffill()

# Show exactly which series loaded — helps diagnose any pull failures
print(f"\n  Columns successfully loaded : {list(macro_df.columns)}")
missing_series = [s for s in FRED_SERIES.keys() if s not in macro_df.columns]
if missing_series:
    print(f"  ⚠  Series NOT loaded (will be skipped): {missing_series}")
    print(f"     Possible causes: FRED rate limit, invalid API key, or series temporarily unavailable.")
    print(f"     These series will be excluded from stationarity tests and macro analysis.")

# Yield curve inversion — only compute if both yield series loaded
if "DGS2" in macro_df.columns and "DGS10" in macro_df.columns:
    macro_df["INVERSION_FLAG"] = (macro_df["DGS2"] > macro_df["DGS10"]).astype(int)
    inv_days = int(macro_df["INVERSION_FLAG"].sum())
    print(f"\n  Yield curve inversion days : {inv_days}")
else:
    macro_df["INVERSION_FLAG"] = 0
    inv_days = 0
    print("\n  ⚠  DGS2 or DGS10 missing — inversion flag set to 0.")

macro_df.to_csv("data/macro_series.csv")
print("  Saved → data/macro_series.csv\n")

print(f"  {'Series':<20s}  {'ADF stat':>9s}  {'p-value':>9s}  {'Stationary?':>12s}  Note")
print(f"  {'─'*20}  {'─'*9}  {'─'*9}  {'─'*12}  {'─'*35}")
stationarity_rows = []
for col in FRED_SERIES.keys():
    # Skip if series didn't load
    if col not in macro_df.columns:
        print(f"  {col:<20s}  {'─':>9s}  {'─':>9s}  {'SKIPPED':>12s}  Series not loaded")
        continue
    # Skip if too few observations for ADF test (need at least 20)
    series_clean = macro_df[col].dropna()
    if len(series_clean) < 20:
        print(f"  {col:<20s}  {'─':>9s}  {'─':>9s}  {'SKIPPED':>12s}  Too few obs ({len(series_clean)})")
        continue
    try:
        result  = adfuller(series_clean, autolag="AIC")
        is_stat = result[1] < 0.05
        note    = "Use levels" if is_stat else "Use first differences in Phase 4 OLS"
        print(f"  {col:<20s}  {result[0]:>9.3f}  {result[1]:>9.4f}  {'YES' if is_stat else 'NO':>12s}  {note}")
        stationarity_rows.append({"series": col, "adf_stat": round(result[0],4),
                                   "p_value": round(result[1],6), "is_stationary": is_stat,
                                   "lags_used": result[2]})
    except Exception as e:
        print(f"  {col:<20s}  ADF failed: {e}")

stat_df = pd.DataFrame(stationarity_rows).set_index("series") if stationarity_rows else pd.DataFrame()
stat_df.to_csv("data/macro_stationarity.csv")
print("\n  Saved → data/macro_stationarity.csv")
print()

# =============================================================================
# SECTION 7 — STATIC COVARIANCE
# =============================================================================

print("SECTION 7 — Static 252-Day Rolling Covariance Matrix")
print("─" * 70)

latest_cov_static = daily_log_returns.iloc[-ROLLING_WINDOW:].cov() * ROLLING_WINDOW
port_var_static   = float(WEIGHTS @ latest_cov_static.values @ WEIGHTS)
port_vol_static   = np.sqrt(port_var_static)
latest_cov_static.to_csv("data/cov_static_latest.csv")
print(f"  Portfolio annualised vol (static) : {port_vol_static*100:.2f}%")
print("  Saved → data/cov_static_latest.csv\n")

# =============================================================================
# SECTION 8 — EWMA COVARIANCE
# =============================================================================

print("SECTION 8 — EWMA Covariance Matrix  (λ=0.94)")
print("─" * 70)

def build_ewma_covariance(returns_df, lam):
    r = returns_df.values
    T, N = r.shape
    cov = np.cov(r[:60].T, bias=False)
    for t in range(60, T):
        rt  = r[t-1].reshape(-1,1)
        cov = lam * cov + (1-lam) * (rt @ rt.T)
    return pd.DataFrame(cov, index=returns_df.columns, columns=returns_df.columns)

ewma_cov            = build_ewma_covariance(daily_log_returns, LAMBDA_EWMA)
ewma_cov_annualised = ewma_cov * ROLLING_WINDOW
port_var_ewma       = float(WEIGHTS @ ewma_cov_annualised.values @ WEIGHTS)
port_vol_ewma       = np.sqrt(port_var_ewma)
ewma_cov_annualised.to_csv("data/cov_ewma_latest.csv")

r_port = portfolio_daily.values
ewma_port_var = np.zeros(len(r_port))
ewma_port_var[0] = r_port[0]**2
for t in range(1, len(r_port)):
    ewma_port_var[t] = LAMBDA_EWMA * ewma_port_var[t-1] + (1-LAMBDA_EWMA) * r_port[t-1]**2

ewma_port_vol_series = pd.Series(np.sqrt(ewma_port_var)*np.sqrt(252),
                                  index=portfolio_daily.index, name="ewma_annualised_vol")
ewma_port_vol_series.to_csv("data/portfolio_ewma_vol.csv")

print(f"  Portfolio EWMA annualised vol  : {port_vol_ewma*100:.2f}%")
print(f"  Portfolio static annualised vol: {port_vol_static*100:.2f}%")
print(f"  Difference (EWMA − static)     : {(port_vol_ewma-port_vol_static)*100:+.2f}%")
print("  Saved → data/cov_ewma_latest.csv, portfolio_ewma_vol.csv\n")

# =============================================================================
# SECTION 9 — CROSS-ASSET CORRELATION
# =============================================================================

print("SECTION 9 — Cross-Asset Correlation (Regime Shift Analysis)")
print("─" * 70)

equity_avg = daily_log_returns[EQUITY_LIST].mean(axis=1)
tlt_ret    = daily_log_returns["TLT"]
gld_ret    = daily_log_returns["GLD"]

corr_windows = {
    "Full sample (2017–2024)"    : ("2017-01-01","2024-12-31"),
    "Pre-COVID calm (2019)"      : ("2019-01-01","2019-12-31"),
    "COVID crash (Feb–Apr 2020)" : ("2020-02-20","2020-04-07"),
    "Post-COVID rally (2021)"    : ("2021-01-01","2021-12-31"),
    "2022 rate shock"            : ("2022-01-01","2022-12-31"),
    "2023 recovery"              : ("2023-01-01","2023-12-31"),
}

print(f"  {'Period':<35s}  {'Equity–TLT':>12s}  {'Equity–GLD':>12s}")
print(f"  {'─'*35}  {'─'*12}  {'─'*12}")
corr_results = {}
for label, (s, e) in corr_windows.items():
    eq    = equity_avg.loc[s:e]
    c_tlt = round(float(eq.corr(tlt_ret.loc[s:e])), 4)
    c_gld = round(float(eq.corr(gld_ret.loc[s:e])), 4)
    corr_results[label] = {"equity_tlt": c_tlt, "equity_gld": c_gld}
    print(f"  {label:<35s}  {c_tlt:>+12.4f}  {c_gld:>+12.4f}")

print("\n  KEY INSIGHT: Equity–TLT correlation turned POSITIVE in 2022.")
print("  Bonds did NOT hedge equity losses during the rate shock.\n")

# =============================================================================
# SECTION 10 — SAVE METADATA
# =============================================================================

print("SECTION 10 — Saving Metadata & Data Dictionary")
print("─" * 70)

PARAMS = {
    "all_tickers": ALL_TICKERS, "equity_list": EQUITY_LIST, "cross_asset": CROSS_ASSET,
    "equity_tickers_by_sector": EQUITY_TICKERS, "weights": WEIGHTS.tolist(),
    "n_assets": N_ASSETS, "start_date": START_DATE, "end_date": END_DATE,
    "train_start": TRAIN_START, "train_end": TRAIN_END,
    "test_start": TEST_START, "test_end": TEST_END,
    "lambda_ewma": LAMBDA_EWMA, "ewma_half_life_days": half_life,
    "rolling_window": ROLLING_WINDOW, "conf_95": CONF_95, "conf_99": CONF_99,
    "conf_es": CONF_ES, "outlier_sigma": OUTLIER_SIGMA,
    "n_monte_carlo": N_MONTE_CARLO, "random_seed": RANDOM_SEED,
    "garch_p": GARCH_P, "garch_q": GARCH_Q, "tgarch_o": TGARCH_O,
    "max_position_wt": MAX_POSITION_WT, "max_sector_wt": MAX_SECTOR_WT,
    "target_return_ann": TARGET_RETURN_ANN, "adv_window": ADV_WINDOW,
    "max_adv_pct": MAX_ADV_PCT,
    "port_vol_static_ann": round(port_vol_static, 6),
    "port_vol_ewma_ann": round(port_vol_ewma, 6),
    "max_drawdown": round(float(drawdown.min()), 6),
    "max_drawdown_date": str(drawdown.idxmin().date()),
    "yield_inversion_days": inv_days,
    "n_outliers_total": total_outliers,
    "n_nonnormal_assets": n_nonnormal,
    "correlation_results": corr_results,
}

with open("data/metadata.json", "w") as f:
    json.dump(PARAMS, f, indent=2, default=str)
with open("data/data_dictionary.json", "w") as f:
    json.dump(DATA_DICTIONARY, f, indent=2)
print("  Saved → data/metadata.json")
print("  Saved → data/data_dictionary.json\n")

