# shared style constants
TITLE_FS   = 14
LABEL_FS   = 11
TICK_FS    = 9
ANNOT_FS   = 9
C_RED      = "#C0392B"
C_ORANGE   = "#E67E22"
C_BLUE     = "#2980B9"
C_GREEN    = "#27AE60"
C_STEEL    = "#2C3E50"
C_GREY     = "#7F8C8D"
COVID_SPAN = (pd.Timestamp("2020-02-20"), pd.Timestamp("2020-04-07"))
RATE_SPAN  = (pd.Timestamp("2022-01-01"), pd.Timestamp("2022-12-31"))

def add_regime_spans(ax):
    ax.axvspan(*COVID_SPAN, alpha=0.10, color=C_RED,    zorder=0)
    ax.axvspan(*RATE_SPAN,  alpha=0.09, color=C_ORANGE, zorder=0)

def style_ax(ax, xlabel=None, ylabel=None):
    ax.tick_params(labelsize=TICK_FS)
    ax.grid(True, alpha=0.25, lw=0.6)
    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)
    if xlabel: ax.set_xlabel(xlabel, fontsize=LABEL_FS)
    if ylabel: ax.set_ylabel(ylabel, fontsize=LABEL_FS)

