# ── PLOT 10: EWMA vs Static Volatility ────────────────────────────────────────
selected = ["AAPL", "JPM", "XOM", "TLT"]
fig, axes = plt.subplots(2, 2, figsize=(16, 9), sharex=True)
fig.subplots_adjust(hspace=0.35, wspace=0.25)

for i, ticker in enumerate(selected):
    ax  = axes[i//2][i%2]
    col = daily_log_returns[ticker]

    static_vol = col.rolling(21).std() * np.sqrt(252) * 100
    r_arr = col.values
    ewv   = np.zeros(len(r_arr))
    ewv[0] = r_arr[0]**2
    for t in range(1, len(r_arr)):
        ewv[t] = LAMBDA_EWMA*ewv[t-1] + (1-LAMBDA_EWMA)*r_arr[t-1]**2
    ewma_vol = pd.Series(np.sqrt(ewv)*np.sqrt(252)*100, index=col.index)

    ax.plot(static_vol.index, static_vol.values, lw=1.1, alpha=0.70,
            color="#2980B9", label="21-day rolling (static)")
    ax.plot(ewma_vol.index, ewma_vol.values, lw=1.6,
            color=C_ORANGE, label=f"EWMA  λ={LAMBDA_EWMA}")
    add_regime_spans(ax)
    ax.set_title(ticker, fontsize=12, fontweight="bold")
    style_ax(ax, ylabel="Annualised Vol (%)")
    ax.yaxis.set_major_formatter(plt.FuncFormatter(lambda x, _: f"{x:.0f}%"))
    ax.legend(fontsize=8.5, framealpha=0.9)

fig.suptitle("Plot 10 — EWMA vs Static Rolling Volatility  (selected assets)\n"
             "EWMA reacts faster to spikes → key motivation for dynamic VaR in Phase 2b",
             fontsize=TITLE_FS, fontweight="bold", y=1.02)
