print("SECTION 12 — Interactive Visualizations (Plotly)")
print("─" * 70)

PLOTLY_TEMPLATE = "plotly_white"
PLOTLY_FONT     = dict(family="Arial, sans-serif", size=12, color="#2C3E50")

def plotly_base_layout(title_text, subtitle_text, height=520):
    return dict(
        title=dict(
            text=f"<b>{title_text}</b><br><sup style='color:#7F8C8D'>{subtitle_text}</sup>",
            font=dict(size=15, family="Arial, sans-serif", color="#2C3E50"),
            x=0.02, xanchor="left"
        ),
        font=PLOTLY_FONT,
        template=PLOTLY_TEMPLATE,
        height=height,
        margin=dict(l=60, r=40, t=80, b=60),
        hovermode="x unified",
        plot_bgcolor="white",
        paper_bgcolor="white",
    )

def add_regime_vrect(fig, row=None, col=None):
    kwargs = {"layer": "below"}
    if row: kwargs.update({"row": row, "col": col})
    fig.add_vrect(x0="2020-02-20", x1="2020-04-07",
                  fillcolor="#E74C3C", opacity=0.07,
                  annotation_text="COVID", annotation_position="top left",
                  annotation_font=dict(size=10, color="#C0392B"), **kwargs)
    fig.add_vrect(x0="2022-01-01", x1="2022-12-31",
                  fillcolor="#E67E22", opacity=0.07,
                  annotation_text="Rate Shock", annotation_position="top left",
                  annotation_font=dict(size=10, color="#E67E22"), **kwargs)

