# =============================================================================
# 0. LOAD DATA
# =============================================================================

print("=" * 70)
print("PHASE 2b — Dynamic VaR: FHS with EWMA / GARCH / T-GARCH")
print("=" * 70)
print()

port = pd.read_csv("data/portfolio_daily_returns.csv",
                   index_col=0, parse_dates=True)["portfolio_return"]

with open("data/metadata.json") as f:
    meta = json.load(f)
with open("results/phase2_var_results.json") as f:
    ph2 = json.load(f)

TRAIN_START = meta["train_start"]; TRAIN_END = meta["train_end"]
TEST_START  = meta["test_start"];  TEST_END  = meta["test_end"]
LAM         = meta["lambda_ewma"]
STATIC_VAR95 = ph2["hs_var_95"]   # decimal

train = port.loc[TRAIN_START:TRAIN_END]
test  = port.loc[TEST_START:TEST_END]
N_TR, N_TE = len(train), len(test)

print(f"  Full history : {port.index[0].date()} → {port.index[-1].date()}")
print(f"  Training     : {TRAIN_START} → {TRAIN_END}  ({N_TR} days)")
print(f"  Test (2022)  : {TEST_START} → {TEST_END}   ({N_TE} days)")
