# =============================================================================
# HELPER: run GARCH or TGARCH on a return array (decimal) → (VaR95, VaR99)
# =============================================================================

def fhs_var(r_decimal, model_type="garch"):
    """
    Fit GARCH or T-GARCH on a window of decimal returns.
    Returns (var95, var99) in decimal form.

    Steps:
      1. Convert to % for arch fitting.
      2. Fit model.
      3. Get conditional vol series (% → decimal).
      4. Standardise: z_t = r_t / σ_t  (both decimal → dimensionless).
      5. One-step forecast vol (decimal).
      6. FHS scenarios = z_t × σ_forecast (decimal).
      7. VaR = percentile of -scenarios.
    """
    r_pct = r_decimal * 100           # % for arch
    o     = 1 if model_type == "tgarch" else 0
    am    = arch_model(r_pct, vol="GARCH", p=1, o=o, q=1, dist="normal")
    res   = am.fit(disp="off", show_warning=False)

    cond_vol_dec = np.array(res.conditional_volatility) / 100   # % → decimal
    cond_vol_dec = np.where(cond_vol_dec < 1e-9, 1e-9, cond_vol_dec)

    fc_var_pct  = float(res.forecast(horizon=1).variance.iloc[-1].values[0])
    fc_vol_dec  = np.sqrt(fc_var_pct) / 100   # % std → decimal

    z_t       = r_decimal / cond_vol_dec        # dimensionless standardised residuals
    scenarios = z_t * fc_vol_dec                # decimal returns

    v95 = float(np.percentile(-scenarios, 95))
    v99 = float(np.percentile(-scenarios, 99))
    return v95, v99, res

# =============================================================================
# STEP 1 — EWMA
# =============================================================================

print("─" * 70)
print("STEP 1 — EWMA Volatility  (λ=0.94, RiskMetrics)")
print("─" * 70)

def ewma_vol_series(r_arr, lam):
    """Compute EWMA variance series for a return array (decimal)."""
    var = np.zeros(len(r_arr))
    var[0] = r_arr[0]**2
    for t in range(1, len(r_arr)):
        var[t] = lam * var[t-1] + (1-lam) * r_arr[t-1]**2
    return var                # variance series (decimal²)

def fhs_ewma_var(r_decimal, lam):
    """FHS-EWMA VaR in decimal form."""
    var_s  = ewma_vol_series(r_decimal, lam)
    vol_s  = np.where(np.sqrt(var_s) < 1e-9, 1e-9, np.sqrt(var_s))
    fc_vol = np.sqrt(lam * var_s[-1] + (1-lam) * r_decimal[-1]**2)
    z_t    = r_decimal / vol_s
    scen   = z_t * fc_vol
    return float(np.percentile(-scen, 95)), float(np.percentile(-scen, 99))

# Static EWMA estimate on training window
r_train = train.values
ewma_var_train = ewma_vol_series(r_train, LAM)
ewma_vol_train = np.sqrt(ewma_var_train)
fc_ewma_vol    = np.sqrt(LAM*ewma_var_train[-1] + (1-LAM)*r_train[-1]**2)

ewma_v95, ewma_v99 = fhs_ewma_var(r_train, LAM)

print(f"  Forecast EWMA daily vol : {fc_ewma_vol*100:.4f}%")
print(f"  FHS-EWMA VaR 95%        : {ewma_v95*100:.4f}%")
print(f"  FHS-EWMA VaR 99%        : {ewma_v99*100:.4f}%")

# Rolling EWMA VaR over test period
print("  Building EWMA rolling VaR for 2022 …")
ewma95_ts, ewma99_ts = [], []
for date in test.index:
    ti   = port.index.get_loc(date)
    r_w  = port.values[max(0, ti-N_TR):ti]     # decimal window
    v95, v99 = fhs_ewma_var(r_w, LAM)
    ewma95_ts.append(v95); ewma99_ts.append(v99)

ewma95_ts = pd.Series(ewma95_ts, index=test.index)
ewma99_ts = pd.Series(ewma99_ts, index=test.index)
print(f"  Done ({N_TE} estimates).\n")

# EWMA vol for full history (for plots)
ewma_var_full  = ewma_vol_series(port.values, LAM)
ewma_vol_full  = pd.Series(np.sqrt(ewma_var_full)*100, index=port.index)

# =============================================================================
# STEP 2 — GARCH(1,1)
# =============================================================================

print("─" * 70)
