for date in test.index:
    ti  = port.index.get_loc(date)
    r_w = port.values[max(0, ti-N_TR):ti]
    try:
        v95, v99, _ = fhs_var(r_w, "garch")
    except Exception:
        v95 = g95_ts[-1] if g95_ts else garch_v95
        v99 = g99_ts[-1] if g99_ts else garch_v99
    g95_ts.append(v95); g99_ts.append(v99)

garch95_ts = pd.Series(g95_ts, index=test.index)
garch99_ts = pd.Series(g99_ts, index=test.index)
print(f"  Done ({N_TE} estimates).\n")

# =============================================================================
# STEP 3 — GJR-GARCH / T-GARCH
# =============================================================================

print("─" * 70)
print("STEP 3 — GJR-GARCH / T-GARCH  (Asymmetric — Leverage Effect)")
print("─" * 70)

tgarch_v95, tgarch_v99, res_t = fhs_var(r_train, "tgarch")
