br_g = breach_garch.sum()   / N_TE
br_t = breach_tgarch.sum()  / N_TE

MODEL_NAMES  = ["Static HS-VaR","FHS-EWMA","FHS-GARCH","FHS-T-GARCH"]
BREACH_CNTS  = [breach_static.sum(), breach_ewma.sum(),
                breach_garch.sum(),  breach_tgarch.sum()]
BREACH_RATES = [br_s, br_e, br_g, br_t]

print(f"  {'Model':<22s}  {'Breaches':>8s}  {'Rate':>8s}  {'Expected':>10s}  Result")
print(f"  {'─'*22}  {'─'*8}  {'─'*8}  {'─'*10}  {'─'*8}")
for nm, nb, br in zip(MODEL_NAMES, BREACH_CNTS, BREACH_RATES):
    res = "PASS ✓" if br <= 0.065 else "FAIL ✗"
    print(f"  {nm:<22s}  {nb:>8d}  {br*100:>7.1f}%  {'5.0%':>10s}  {res}")
print()

# =============================================================================
# STEP 5 — KUPIEC TEST
# =============================================================================

print("─" * 70)
print("STEP 5 — Kupiec LR Test")
print("─" * 70)
print("  H₀: breach rate = 5%   Critical value = 3.84 (χ²(1), α=5%)")
print()

def kupiec(n_breach, n_obs, conf=0.95):
    p = 1 - conf; x = n_breach; T = n_obs
    p_hat = x / T
    if x == 0:   lr = -2*T*np.log(1-p)
    elif x == T: lr = -2*T*np.log(p)
    else:
        lr = -2*(x*np.log(p) + (T-x)*np.log(1-p)
                 - x*np.log(p_hat) - (T-x)*np.log(1-p_hat))
    pv = 1 - stats.chi2.cdf(lr, df=1)
    return round(lr,4), round(pv,6)

kup_res = []
print(f"  {'Model':<22s}  {'N':>5s}  {'Rate':>7s}  {'LR':>8s}  {'p':>9s}  Result")
print(f"  {'─'*22}  {'─'*5}  {'─'*7}  {'─'*8}  {'─'*9}  {'─'*8}")
for nm, nb, br in zip(MODEL_NAMES, BREACH_CNTS, BREACH_RATES):
    lr, pv = kupiec(nb, N_TE)
    passed = pv > 0.05
    kup_res.append({"model":nm,"n_breaches":int(nb),"breach_rate":round(br,5),
                    "LR_stat":lr,"p_value":pv,"pass":passed})
    print(f"  {nm:<22s}  {nb:>5d}  {br*100:>6.1f}%  {lr:>8.3f}  {pv:>9.4f}  "
          f"{'PASS ✓' if passed else 'FAIL ✗'}")

print()
best_model = min(kup_res, key=lambda r: r["LR_stat"])
print(f"  Best model by Kupiec: {best_model['model']} "
      f"(LR={best_model['LR_stat']:.3f}, breach rate={best_model['breach_rate']*100:.1f}%)")
print()

# Christoffersen independence test
def christoffersen(breach_s):
    b = breach_s.values.astype(int)
    n00=n01=n10=n11=0
    for i in range(1, len(b)):
        if   b[i-1]==0 and b[i]==0: n00+=1
        elif b[i-1]==0 and b[i]==1: n01+=1
        elif b[i-1]==1 and b[i]==0: n10+=1
        else:                        n11+=1
    tot = n00+n01+n10+n11
    if (n00+n01)==0 or (n10+n11)==0 or tot==0: return np.nan, np.nan
    pi01 = n01/(n00+n01); pi11 = n11/(n10+n11) if (n10+n11)>0 else 0
    pi   = (n01+n11)/tot
    if pi in (0,1) or pi01==0 or pi11==0: return np.nan, np.nan
    lr = -2*((n00+n10)*np.log(1-pi)+(n01+n11)*np.log(pi)
             -n00*np.log(1-pi01)-n01*np.log(pi01)
             -n10*np.log(1-pi11 if pi11<1 else 1e-9)
             -n11*np.log(pi11   if pi11>0 else 1e-9))
    return round(lr,4), round(1-stats.chi2.cdf(lr,1),6)

print("  Christoffersen Independence Test (H₀: breaches are not clustered):")
print(f"  {'Model':<22s}  {'LR':>8s}  {'p':>9s}  Independence")
print(f"  {'─'*22}  {'─'*8}  {'─'*9}  {'─'*15}")
for nm, br_s_ser in zip(MODEL_NAMES,
                        [breach_static,breach_ewma,breach_garch,breach_tgarch]):
    lr_c, pv_c = christoffersen(br_s_ser)
    if np.isnan(lr_c):
        print(f"  {nm:<22s}  {'n/a':>8s}  {'n/a':>9s}  —")
    else:
        res = "Independent ✓" if pv_c>0.05 else "Clustered ✗"
        print(f"  {nm:<22s}  {lr_c:>8.3f}  {pv_c:>9.4f}  {res}")
print()

