# Score each model 0-100 on 5 dimensions
# Higher = better on every axis (so we invert where lower = better)
max_br   = max(BREACH_RATES)
max_lr   = max(r["LR_stat"] for r in kup_res)

def sc(val, max_v): return round(max(0, 1 - val/max_v)*100, 1)

radar_data = [
    {
        "name"   : "Static HS-VaR",
        "scores" : [sc(br_s, max_br), sc(kup_res[0]["LR_stat"], max_lr),
                    0, 100, 0],
        "color"  : C_STATIC
    },
    {
        "name"   : "FHS-EWMA",
        "scores" : [sc(br_e, max_br), sc(kup_res[1]["LR_stat"], max_lr),
                    75, 85, 25],
        "color"  : C_EWMA
    },
    {
        "name"   : "FHS-GARCH",
        "scores" : [sc(br_g, max_br), sc(kup_res[2]["LR_stat"], max_lr),
                    80, 60, 40],
        "color"  : C_GARCH
    },
    {
        "name"   : "FHS-T-GARCH",
        "scores" : [sc(br_t, max_br), sc(kup_res[3]["LR_stat"], max_lr),
                    85, 50, 100],
        "color"  : C_TGARCH
    },
]

