# Scenario definitions (as specified in the doc)
SCENARIOS = {
    "Bear": {
        "equity_shock"     : -0.30,    # -30% on all equity positions
        "rate_shock_bps"   : +200,     # +200bps rates
        "ig_spread_bps"    : +300,     # IG spreads +300bps
        "hy_spread_bps"    : +600,     # HY spreads +600bps
        "tlt_shock"        : -0.20,    # TLT falls when rates rise (approx duration impact)
        "gld_shock"        : +0.05,    # Gold slight safe-haven bid
        "uup_shock"        : +0.03,    # Dollar strengthens
        "color"            : C_BEAR,
        "description"      : "2022-style aggressive tightening",
    },
    "Base": {
        "equity_shock"     : +0.08,
        "rate_shock_bps"   : 0,
        "ig_spread_bps"    : 0,
        "hy_spread_bps"    : 0,
        "tlt_shock"        : +0.02,
        "gld_shock"        : +0.03,
        "uup_shock"        : 0.0,
        "color"            : C_BASE,
        "description"      : "Moderate growth, rates flat",
    },
    "Bull": {
        "equity_shock"     : +0.20,
        "rate_shock_bps"   : -50,
        "ig_spread_bps"    : -50,
        "hy_spread_bps"    : -100,
        "tlt_shock"        : +0.08,    # TLT rallies when rates fall
        "gld_shock"        : +0.04,
        "uup_shock"        : -0.02,
        "color"            : C_BULL,
        "description"      : "Rate cuts + spread compression",
    },
}

# Per-asset sector map for applying shocks
SECTOR_MAP = {t: "equity" for t in EQUITY_LIST}
SECTOR_MAP.update({"TLT": "tlt", "GLD": "gld", "UUP": "uup"})

def apply_scenario(scenario_name, scenario_def):
    """
    Apply scenario shocks to each asset.
    Returns per-asset P&L and total portfolio P&L (assuming $1 portfolio).
    Equity shock applied to all equity tickers.
    TLT/GLD/UUP get their own shocks.
    """
    pnl_per_asset = {}
    for ticker, weight in zip(ALL_TICKERS, WEIGHTS):
        sec = SECTOR_MAP[ticker]
        if sec == "equity":
            shock = scenario_def["equity_shock"]
        elif sec == "tlt":
            shock = scenario_def["tlt_shock"]
        elif sec == "gld":
            shock = scenario_def["gld_shock"]
        else:
            shock = scenario_def["uup_shock"]
        pnl_per_asset[ticker] = shock * weight   # weighted contribution

    total_pnl = sum(pnl_per_asset.values())
    return pnl_per_asset, total_pnl

scenario_results = {}
print(f"  {'Scenario':<8s}  {'Portfolio P&L':>14s}  {'vs Static VaR':>16s}  Description")
print(f"  {'─'*8}  {'─'*14}  {'─'*16}  {'─'*35}")

for sname, sdef in SCENARIOS.items():
    pnl_dict, total_pnl = apply_scenario(sname, sdef)
    vs_var = total_pnl / (-STATIC_VAR95)   # how many daily VaRs is this shock
    scenario_results[sname] = {
        "per_asset_pnl": pnl_dict,
        "total_pnl"    : round(total_pnl, 6),
        "pnl_pct"      : round(total_pnl * 100, 2),
        "vs_var_95"    : round(vs_var, 2),
        "rate_bps"     : sdef["rate_shock_bps"],
        "ig_bps"       : sdef["ig_spread_bps"],
        "hy_bps"       : sdef["hy_spread_bps"],
        "color"        : sdef["color"],
        "description"  : sdef["description"],
    }
    print(f"  {sname:<8s}  {total_pnl*100:>+13.2f}%  {vs_var:>+15.1f}×  {sdef['description']}")

print()
print("  NOTE: Equity shock is applied as total return over the scenario horizon.")
print("  TLT shock computed via approximate duration × rate shock.")
print("  These are instantaneous P&L impacts, not VaR estimates.")
print()

