COVID_START = "2020-02-20"
COVID_END   = "2020-04-07"

covid_returns = portfolio_daily.loc[COVID_START:COVID_END]
covid_cum_ret = (1 + covid_returns).cumprod()
covid_drawdown = (covid_cum_ret - covid_cum_ret.cummax()) / covid_cum_ret.cummax()

covid_peak_to_trough = covid_drawdown.min()
covid_trough_date    = covid_drawdown.idxmin()
covid_total_return   = float(covid_cum_ret.iloc[-1] - 1)
covid_max_single_day = covid_returns.min()
covid_worst_day      = covid_returns.idxmin()

# Per-asset drawdown during COVID
asset_covid_ret = daily_returns.loc[COVID_START:COVID_END]
asset_covid_cum = (1 + asset_covid_ret).cumprod()
asset_covid_dd  = {}
for ticker in ALL_TICKERS:
    cum = asset_covid_cum[ticker]
    dd  = (cum - cum.cummax()) / cum.cummax()
    asset_covid_dd[ticker] = float(dd.min())

print(f"  Period            : {COVID_START} → {COVID_END}  ({len(covid_returns)} trading days)")
print(f"  Peak-to-trough DD : {covid_peak_to_trough*100:.2f}%  on {covid_trough_date.date()}")
print(f"  Total return      : {covid_total_return*100:.2f}%")
print(f"  Worst single day  : {covid_max_single_day*100:.3f}%  on {covid_worst_day.date()}")
print()

# Top 5 worst drawdown assets
worst_covid = sorted(asset_covid_dd.items(), key=lambda x: x[1])[:5]
print("  Worst 5 assets during COVID crash:")
for t, dd in worst_covid:
    print(f"    {t:6s}  {dd*100:.2f}%")
print()

# Best performing (diversifiers)
best_covid = sorted(asset_covid_dd.items(), key=lambda x: x[1], reverse=True)[:3]
print("  Best performers (diversifiers) during COVID:")
for t, dd in best_covid:
    print(f"    {t:6s}  {dd*100:+.2f}%")
print()

