# =============================================================================

print("─" * 70)
print("SECTION 3 — Historical Replay: 2022 Rate Shock")
print("─" * 70)

RATE_START = "2022-01-01"
RATE_END   = "2022-12-31"

rate_returns  = portfolio_daily.loc[RATE_START:RATE_END]
rate_cum_ret  = (1 + rate_returns).cumprod()
rate_drawdown = (rate_cum_ret - rate_cum_ret.cummax()) / rate_cum_ret.cummax()

rate_peak_to_trough = rate_drawdown.min()
rate_trough_date    = rate_drawdown.idxmin()
rate_total_return   = float(rate_cum_ret.iloc[-1] - 1)

# Find which assets breached 10% drawdown and when
DRAWDOWN_LIMIT = -0.10
first_breach_dates = {}
for ticker in ALL_TICKERS:
    cum = (1 + daily_returns.loc[RATE_START:RATE_END, ticker]).cumprod()
    dd  = (cum - cum.cummax()) / cum.cummax()
    breached = dd[dd < DRAWDOWN_LIMIT]
    if len(breached) > 0:
        first_breach_dates[ticker] = breached.index[0].date()

print(f"  Period            : {RATE_START} → {RATE_END}  ({len(rate_returns)} trading days)")
print(f"  Peak-to-trough DD : {rate_peak_to_trough*100:.2f}%  on {rate_trough_date.date()}")
print(f"  Full year return  : {rate_total_return*100:.2f}%")
print()
print(f"  Assets breaching 10% drawdown limit during 2022:")
print(f"  {'Ticker':<8s}  First 10% DD breach")
print(f"  {'─'*8}  {'─'*25}")
for ticker in ALL_TICKERS:
    if ticker in first_breach_dates:
        print(f"  {ticker:<8s}  {first_breach_dates[ticker]}")
    else:
        print(f"  {ticker:<8s}  Never breached 10% DD")
print()

# T-GARCH VaR on key breach dates vs static VaR
print("  T-GARCH VaR vs Static VaR around key breach events (2022):")
print(f"  {'Date':<12s}  {'Actual Loss':>12s}  {'Static VaR':>12s}  {'T-GARCH VaR':>12s}  Signal")
print(f"  {'─'*12}  {'─'*12}  {'─'*12}  {'─'*12}  {'─'*20}")
sample_dates = var_ts.index[::20]   # every 4 weeks
for d in sample_dates:
    actual   = var_ts.loc[d, "actual_loss"]
    static_v = var_ts.loc[d, "var95_static"]
    tgarch_v = var_ts.loc[d, "var95_tgarch"]
    premium  = (tgarch_v - static_v) / static_v * 100
    signal = "ELEVATED ⚠" if tgarch_v > static_v * 1.3 else "normal"
    print(f"  {str(d.date()):<12s}  {actual*100:>11.3f}%  "
          f"{static_v*100:>11.3f}%  {tgarch_v*100:>11.3f}%  {signal}")
print()

