gld_ret    = daily_returns["GLD"]

cross_asset_corr = {}
for label, period in [
    ("Calm 2019",      daily_returns.loc["2019-01-01":"2019-12-31"]),
    ("COVID crash",    daily_returns.loc[COVID_START:COVID_END]),
    ("2022 rate shock",daily_returns.loc[RATE_START:RATE_END]),
]:
    eq  = period[EQUITY_LIST].mean(axis=1)
    c_tlt = round(float(eq.corr(period["TLT"])), 4)
    c_gld = round(float(eq.corr(period["GLD"])), 4)
    c_uup = round(float(eq.corr(period["UUP"])), 4)
    cross_asset_corr[label] = {"TLT": c_tlt, "GLD": c_gld, "UUP": c_uup}

print(f"  {'Period':<22s}  {'Equity–TLT':>12s}  {'Equity–GLD':>12s}  {'Equity–UUP':>12s}")
