print("─" * 70)
print("SECTION 5 — Dynamic VaR After Stress Events")
print("─" * 70)
print("  T-GARCH conditional vol escalates after negative shocks.")
print("  This shows the dynamic VaR was already warning BEFORE the worst months.")
print()

# EWMA vol series for 2022 (from saved data / recompute)
r_full     = portfolio_daily.values
lam        = LAMBDA_EWMA
ewma_var   = np.zeros(len(r_full))
ewma_var[0] = r_full[0]**2
for t in range(1, len(r_full)):
    ewma_var[t] = lam * ewma_var[t-1] + (1-lam) * r_full[t-1]**2

ewma_vol_series = pd.Series(np.sqrt(ewma_var)*100, index=portfolio_daily.index)
ewma_2022 = ewma_vol_series.loc[RATE_START:RATE_END]

# Show vol regime before/during worst stress months
months = ["2022-01","2022-02","2022-03","2022-04","2022-05","2022-06",
          "2022-07","2022-08","2022-09","2022-10","2022-11","2022-12"]
print(f"  {'Month':<8s}  {'EWMA Vol (avg)':>15s}  {'T-GARCH VaR':>12s}  {'Static VaR':>12s}  Vol Regime")
print(f"  {'─'*8}  {'─'*15}  {'─'*12}  {'─'*12}  {'─'*12}")
for m in months:
    ewma_m = ewma_2022.loc[m].mean() if m in ewma_2022.index.strftime("%Y-%m").values else np.nan
    tgarch_m_mean = var_ts.loc[m, "var95_tgarch"].mean() * 100 if m in var_ts.index.strftime("%Y-%m").values else np.nan
    regime = "HIGH 🔴" if ewma_m > 1.2 else "MEDIUM 🟡" if ewma_m > 0.8 else "LOW 🟢"
    print(f"  {m:<8s}  {ewma_m:>14.3f}%  "
          f"{tgarch_m_mean:>11.3f}%  {STATIC_VAR95*100:>11.3f}%  {regime}")
print()

