# ── PLOT 01: Scenario P&L — Asset-type grouped summary (more informative) ────
# Since all equities get the same shock, showing 15 identical bars adds no info.
# Instead: show contribution by ASSET TYPE + total, grouped by scenario.
# This is exactly what a risk committee wants to see.

asset_type_labels = ["Equity (15 stocks)", "TLT (bonds)", "GLD (gold)", "UUP (dollar)", "Total"]

fig, ax = plt.subplots(figsize=(14, 6))
fig.subplots_adjust(bottom=0.12)

x     = np.arange(len(asset_type_labels))
width = 0.22
scen_list = ["Bear", "Base", "Bull"]
scen_cols  = [C_BEAR, C_BASE, C_BULL]
offsets    = [-width, 0, width]

for scen, col, offset in zip(scen_list, scen_cols, offsets):
    res = scenario_results[scen]
    # Equity total contribution
    eq_total  = sum(res["per_asset_pnl"][t]*100 for t in EQUITY_LIST)
    tlt_pnl   = res["per_asset_pnl"]["TLT"] * 100
    gld_pnl   = res["per_asset_pnl"]["GLD"] * 100
    uup_pnl   = res["per_asset_pnl"]["UUP"] * 100
    total_pnl = res["pnl_pct"]

    values = [eq_total, tlt_pnl, gld_pnl, uup_pnl, total_pnl]
    bars   = ax.bar(x + offset, values, width=width*0.92,
                    color=col, edgecolor="white", linewidth=0.6,
                    alpha=0.88, zorder=3, label=f"{scen}  ({total_pnl:+.1f}%)")

    # Label only the Total bar
    bar_total = bars[-1]
    ax.text(bar_total.get_x() + bar_total.get_width()/2,
            total_pnl + (0.4 if total_pnl >= 0 else -0.8),
            f"{total_pnl:+.1f}%",
            ha="center", va="bottom" if total_pnl >= 0 else "top",
            fontsize=9, fontweight="bold", color=col)

ax.axhline(0, color=C_STEEL, lw=0.9, ls="--")
ax.axhline(-STATIC_VAR95*100, color=C_STATIC, lw=1.2, ls=":",
           alpha=0.8, label=f"Daily VaR 95% (−{STATIC_VAR95*100:.2f}%)")

ax.set_xticks(x)
ax.set_xticklabels(asset_type_labels, fontsize=11)
ax.set_title("Plot 01 — Scenario P&L by Asset Type: Bear / Base / Bull\n"
             "Equity dominates all scenarios · TLT provides partial offset in Bull · GLD mild hedge",
             fontsize=TFS, fontweight="bold")
clean_ax(ax, ylabel="P&L Contribution (%)")
ax.legend(fontsize=10, framealpha=0.92, loc="upper right")
ax.yaxis.grid(True, alpha=0.22); ax.set_axisbelow(True)

plt.tight_layout()
plt.savefig("plots/phase3_01_scenario_pnl_per_asset.png", dpi=150, bbox_inches="tight")
plt.show(); plt.close()

# ── PLOT 02: Scenario Summary (3 bars side by side) ───────────────────────────
