# ── PLOT 05: Cross-Asset Correlation — 3 separate readable heatmaps ─────────
import seaborn as sns
periods_p05 = [
    ("Calm 2019",        "2019-01-01", "2019-12-31", C_BULL),
    ("COVID Crash",      COVID_START,  COVID_END,    C_BEAR),
    ("2022 Rate Shock",  RATE_START,   RATE_END,     C_ORANGE),
]

fig, axes = plt.subplots(1, 3, figsize=(22, 8))
fig.subplots_adjust(wspace=0.40)

for ax_i, (label, s, e, col) in enumerate(periods_p05):
    ax  = axes[ax_i]
    sub = daily_returns.loc[s:e][EQUITY_LIST + CROSS_ASSET]
    corr = sub.corr()
    mask = np.triu(np.ones_like(corr, dtype=bool), k=1)
    sns.heatmap(
        corr, mask=mask, annot=True, fmt=".2f",
        cmap="RdYlGn", center=0, vmin=-1, vmax=1,
        linewidths=0.5, linecolor="#f5f5f5",
        ax=ax,
        annot_kws={"size": 8.0, "weight": "bold"},
        cbar_kws={"shrink": 0.75, "label": "Correlation"}
    )
    ax.set_title(label, fontsize=12, fontweight="bold", color=col, pad=10)
    ax.tick_params(axis="x", labelsize=9, rotation=45)
    ax.tick_params(axis="y", labelsize=9, rotation=0)

fig.suptitle("Plot 05 — Correlation Matrix: Calm (2019) vs COVID vs 2022 Rate Shock\n"
             "TLT row: green in COVID (diversifier) → yellow/red in 2022 (failed hedge)",
             fontsize=TFS, fontweight="bold", y=1.02)
plt.savefig("plots/phase3_05_correlation_regimes.png", dpi=150, bbox_inches="tight")
plt.show(); plt.close()

