# Consistent: equity=red, TLT=dark blue, GLD=gold, UUP=purple
cols_covid = ["#E74C3C" if t in EQUITY_LIST else
              C_TLT    if t=="TLT" else
              C_GLD    if t=="GLD" else C_UUP
              for t in covid_dd_sorted.keys()]
ax1.barh(list(covid_dd_sorted.keys()),
         [v*100 for v in covid_dd_sorted.values()],
         color=cols_covid, edgecolor="white", height=0.7, zorder=3)
ax1.axvline(-10, color=C_ORANGE, lw=1.2, ls="--", label="−10% limit")
ax1.axvline(0, color=C_STEEL, lw=0.8)
ax1.set_title("COVID Crash  (Feb–Apr 2020)\nPeak-to-trough drawdown per asset",
              fontsize=10, fontweight="bold")
clean_ax(ax1, xlabel="Peak-to-Trough Drawdown (%)")
ax1.xaxis.set_major_formatter(mticker.FuncFormatter(lambda x,_: f"{x:.0f}%"))
ax1.legend(fontsize=9)
ax1.xaxis.grid(True, alpha=0.22); ax1.set_axisbelow(True)
ax1.legend(handles=[
    mpatches.Patch(color="#E74C3C", label="Equity"),
    mpatches.Patch(color=C_TLT,     label="TLT (bonds)"),
    mpatches.Patch(color=C_GLD,     label="GLD (gold)"),
    mpatches.Patch(color=C_UUP,     label="UUP (dollar)"),
], fontsize=8.5, framealpha=0.9, loc="lower right")

# 2022 drawdowns
rate_dd_dict = {}
for ticker in ALL_TICKERS:
    cum = (1 + daily_returns.loc[RATE_START:RATE_END, ticker]).cumprod()
    dd  = (cum - cum.cummax()) / cum.cummax()
    rate_dd_dict[ticker] = float(dd.min())

rate_dd_sorted = dict(sorted(rate_dd_dict.items(), key=lambda x: x[1]))
cols_rate = ["#E74C3C" if t in EQUITY_LIST else
             C_TLT    if t=="TLT" else
             C_GLD    if t=="GLD" else C_UUP
             for t in rate_dd_sorted.keys()]
ax2.barh(list(rate_dd_sorted.keys()),
         [v*100 for v in rate_dd_sorted.values()],
         color=cols_rate, edgecolor="white", height=0.7, zorder=3)
ax2.axvline(-10, color=C_ORANGE, lw=1.2, ls="--", label="−10% limit")
ax2.axvline(0, color=C_STEEL, lw=0.8)
ax2.set_title("2022 Rate Shock  (Jan–Dec 2022)\nFull year drawdown per asset",
              fontsize=10, fontweight="bold")
clean_ax(ax2, xlabel="Peak-to-Trough Drawdown (%)")
ax2.xaxis.set_major_formatter(mticker.FuncFormatter(lambda x,_: f"{x:.0f}%"))
ax2.legend(fontsize=9)
ax2.xaxis.grid(True, alpha=0.22); ax2.set_axisbelow(True)

fig.suptitle("Plot 06 — Per-Asset Drawdowns: COVID Crash vs 2022 Rate Shock\n"
             "TLT protected in COVID (positive return) but fell in 2022 — regime shift visualised",
             fontsize=TFS, fontweight="bold", y=1.04)
plt.savefig("plots/phase3_06_asset_drawdowns_comparison.png", dpi=150, bbox_inches="tight")
plt.show(); plt.close()

