fig, ax = plt.subplots(figsize=(16, 5))
ax.axis("off")

hdr = ["Scenario","Equity\nShock","Rate\nShock","Portfolio\nP&L",
       "P&L vs\nDaily VaR","TLT\nContrib","GLD\nContrib","Description"]

row_colors_map = {
    "Bear"        : C_BEAR,
    "Base"        : C_BASE,
    "Bull"        : C_BULL,
    "COVID Replay": "#7D6608",
    "2022 Replay" : C_ORANGE,
}
