"""
=============================================================================
PROJECT — Portfolio Risk, Stress Testing & Macro Scenario Engine
PHASE 4  — Macro-to-Portfolio Linkage
=============================================================================

=============================================================================
"""

import os, json, warnings
import numpy as np
import pandas as pd
import scipy.stats as stats
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
import matplotlib.ticker as mticker
import statsmodels.api as sm
from statsmodels.tsa.stattools import grangercausalitytests, adfuller
from statsmodels.stats.sandwich_covariance import cov_hac
import plotly.graph_objects as go
from plotly.subplots import make_subplots

warnings.filterwarnings("ignore")
os.makedirs("plots",   exist_ok=True)
os.makedirs("results", exist_ok=True)

plt.rcParams.update({
    "figure.dpi": 150, "font.family": "DejaVu Sans", "font.size": 10,
    "axes.spines.top": False, "axes.spines.right": False,
    "axes.grid": True, "grid.alpha": 0.22, "grid.linewidth": 0.6,
})
TFS = 13; LFS = 10; AFS = 9
C_MACRO = "#2C3E50"; C_RATE  = "#2980B9"; C_CPI   = "#E67E22"
C_SPREAD= "#C0392B"; C_PORT  = "#229954"; C_TGARCH= "#C0392B"
C_STEEL = "#1C2833"; C_GREY  = "#7F8C8D"

def clean_ax(ax, xlabel=None, ylabel=None):
    ax.tick_params(labelsize=AFS)
    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)
    if xlabel: ax.set_xlabel(xlabel, fontsize=LFS)
    if ylabel: ax.set_ylabel(ylabel, fontsize=LFS)

PTEMPLATE = "plotly_white"
PFONT     = dict(family="Arial, sans-serif", size=12, color=C_STEEL)

def playout(title, sub, height=530):
    return dict(
        title=dict(
            text=f"<b>{title}</b><br><sup style='color:#7F8C8D'>{sub}</sup>",
            font=dict(size=15, family="Arial, sans-serif", color=C_STEEL),
            x=0.02, xanchor="left"),
        font=PFONT, template=PTEMPLATE, height=height,
        margin=dict(l=70, r=50, t=90, b=65),
        hovermode="x unified",
        plot_bgcolor="white", paper_bgcolor="white",
    )

# =============================================================================
# 0. LOAD DATA
# =============================================================================

print("=" * 70)
print("PHASE 4 — Macro-to-Portfolio Linkage")
print("=" * 70)
print()

portfolio_monthly = pd.read_csv(
    "data/portfolio_monthly_returns.csv", index_col=0, parse_dates=True
)["portfolio_return"]

portfolio_daily = pd.read_csv(
    "data/portfolio_daily_returns.csv", index_col=0, parse_dates=True
)["portfolio_return"]

macro_df = pd.read_csv("data/macro_series.csv", index_col=0, parse_dates=True)
stat_df  = pd.read_csv("data/macro_stationarity.csv", index_col=0)

with open("data/metadata.json") as f:
    meta = json.load(f)
with open("results/phase2_var_results.json") as f:
    ph2 = json.load(f)

var_ts = pd.read_csv("results/phase2b_var_timeseries_2022.csv",
                      index_col=0, parse_dates=True)

LAMBDA_EWMA  = meta["lambda_ewma"]
STATIC_VAR95 = ph2["hs_var_95"]

print(f"  Portfolio monthly returns : {len(portfolio_monthly)} obs")
print(f"  Macro series loaded       : {list(macro_df.columns)}")
print()

# =============================================================================
# SECTION 1 — MACRO DATA PREPARATION
# =============================================================================

print("─" * 70)
print("SECTION 1 — Macro Data Preparation (Stationarity-Guided Differencing)")
print("─" * 70)
print("  ADF results from Phase 1:")
print("  FEDFUNDS, CPIAUCSL, DGS10, DGS2 → NON-STATIONARY → use first differences")
print("  BAMLC0A0CM, BAMLH0A0HYM2        → STATIONARY     → use levels")
print()

macro_monthly = macro_df.resample("ME").last().ffill()

macro_monthly["ΔFFR"]        = macro_monthly["FEDFUNDS"].diff()
macro_monthly["ΔCPI"]        = macro_monthly["CPIAUCSL"].pct_change() * 100
macro_monthly["Δ10Y"]        = macro_monthly["DGS10"].diff()
macro_monthly["Δ2Y"]         = macro_monthly["DGS2"].diff()
macro_monthly["IG_spread"]   = macro_monthly["BAMLC0A0CM"]
macro_monthly["HY_spread"]   = macro_monthly["BAMLH0A0HYM2"]
macro_monthly["ΔIG_spread"]  = macro_monthly["BAMLC0A0CM"].diff()
macro_monthly["INVERSION"]   = macro_monthly["INVERSION_FLAG"]

# ── FIX: only include columns with full history in reg_df ─────────────────────
# IG_spread / HY_spread / ΔIG_spread only start 2023 in this FRED pull
# → exclude them from reg_df to avoid dropna() wiping 2017-2022 rows
# They are still available in macro_monthly for Granger tests (Section 4)
cols_to_use = ["ΔFFR", "ΔCPI", "Δ10Y", "INVERSION"]
for col in ["ΔIG_spread"]:
    fv = macro_monthly[col].first_valid_index()
    if fv is not None and fv.year <= 2018:
        cols_to_use.append(col)
        print(f"  ✓  {col} included in regression (starts {fv.date()})")
    else:
        print(f"  ⚠  {col} excluded from regression (starts {fv} — too recent)")

reg_df = pd.concat([
    portfolio_monthly.rename("port_return"),
    macro_monthly[cols_to_use],
], axis=1).dropna()

print(f"\n  Regression dataset: {len(reg_df)} monthly obs "
      f"({reg_df.index[0].strftime('%Y-%m')} → {reg_df.index[-1].strftime('%Y-%m')})")
print()
print(f"  {'Variable':<15s}  {'Mean':>8s}  {'Std':>8s}  {'Min':>8s}  {'Max':>8s}  Notes")
print(f"  {'─'*15}  {'─'*8}  {'─'*8}  {'─'*8}  {'─'*8}  {'─'*25}")
for col, note in [
    ("port_return","Portfolio monthly return (%)"),
    ("ΔFFR",       "ΔFed Funds Rate (bps/month)"),
    ("ΔCPI",       "ΔCPI % MoM"),
    ("Δ10Y",       "Δ10Y yield (bps/month)"),
    ("ΔIG_spread", "ΔIG spread (bps/month)"),
]:
    if col in reg_df.columns:
        s = reg_df[col]
        print(f"  {col:<15s}  {s.mean():>8.3f}  {s.std():>8.3f}  "
              f"{s.min():>8.3f}  {s.max():>8.3f}  {note}")
print()

# =============================================================================
# SECTION 2 — OLS REGRESSION
# =============================================================================

print("─" * 70)
print("SECTION 2 — OLS Regression: Portfolio Returns ~ Macro Factors")
print("─" * 70)
print("  Model: R_port = α + β₁·ΔFFR + β₂·ΔCPI + β₃·Δ10Y + ε")
print("  HAC standard errors (Newey-West, 3 lags) to handle autocorrelation.")
print()

y = reg_df["port_return"] * 100

X_cols = [c for c in ["ΔFFR", "ΔCPI", "Δ10Y", "ΔIG_spread"] if c in reg_df.columns]
X = sm.add_constant(reg_df[X_cols])

model  = sm.OLS(y, X)
result = model.fit(cov_type="HAC", cov_kwds={"maxlags": 3})

print(result.summary())
print()

coef_df = pd.DataFrame({
    "coefficient" : result.params,
    "std_error"   : result.bse,
    "t_stat"      : result.tvalues,
    "p_value"     : result.pvalues,
    "significant" : result.pvalues < 0.05,
})

print("─" * 70)
print("MACRO SENSITIVITY TABLE  (CIO Deliverable)")
print("─" * 70)
print("  Interpretation: coefficient × shock = estimated portfolio impact")
print()

sensitivity_table = {
    "Δ10Y +100bps"   : result.params.get("Δ10Y", 0) * 1.0,
    "ΔFFR +100bps"   : result.params.get("ΔFFR", 0) * 1.0,
    "ΔCPI +1%"       : result.params.get("ΔCPI", 0) * 1.0,
    "ΔIG +100bps"    : result.params.get("ΔIG_spread", 0) * 1.0,
    "Δ10Y -100bps"   : result.params.get("Δ10Y", 0) * (-1.0),
    "ΔFFR -100bps"   : result.params.get("ΔFFR", 0) * (-1.0),
}

print(f"  {'Macro Shock':<20s}  {'Portfolio Impact':>18s}  Interpretation")
print(f"  {'─'*20}  {'─'*18}  {'─'*35}")
for shock, impact in sensitivity_table.items():
    direction = "loss" if impact < 0 else "gain"
    print(f"  {shock:<20s}  {impact:>+17.3f}%  Portfolio {direction} of {abs(impact):.2f}%")

print()
print(f"  Model fit: R² = {result.rsquared:.4f}  "
      f"Adj. R² = {result.rsquared_adj:.4f}  "
      f"F-stat p = {result.f_pvalue:.4f}")
print()

# =============================================================================
# SECTION 3 — YIELD CURVE INVERSION SIGNAL
# =============================================================================

print("─" * 70)
print("SECTION 3 — Yield Curve Inversion Signal  (2Y > 10Y)")
print("─" * 70)

inv_flag_daily   = macro_df["INVERSION_FLAG"].dropna()
inv_starts_daily = inv_flag_daily[(inv_flag_daily==1) & (inv_flag_daily.shift(1)==0)].index
inv_starts       = pd.DatetimeIndex([d.to_period("M").to_timestamp() for d in inv_starts_daily])
inv_flag         = macro_monthly["INVERSION"].dropna()

print(f"  Inversion days (monthly): {int(inv_flag.sum())}")
print(f"  Distinct inversion episodes starting: {len(inv_starts)}")
print()

inversion_fwd_returns = []
for start_date in inv_starts:
    end_date = start_date + pd.DateOffset(months=12)
    fwd      = portfolio_monthly.loc[start_date:end_date]
    if len(fwd) >= 6:
        cum_ret = float((1 + fwd).prod() - 1)
        inversion_fwd_returns.append({
            "inversion_start" : start_date.strftime("%Y-%m"),
            "fwd_12m_return"  : round(cum_ret * 100, 2),
            "n_months"        : len(fwd),
        })

inv_df = pd.DataFrame(inversion_fwd_returns)
if len(inv_df) > 0:
    print(f"  {'Inversion Start':<18s}  {'12m Fwd Return':>16s}  {'Months Available':>18s}")
    print(f"  {'─'*18}  {'─'*16}  {'─'*18}")
    for _, row in inv_df.iterrows():
        ret_col = "↓ LOSS" if row["fwd_12m_return"] < 0 else "↑ GAIN"
        print(f"  {row['inversion_start']:<18s}  {row['fwd_12m_return']:>+15.2f}%  "
              f"{row['n_months']:>17d}  {ret_col}")
    avg_fwd = inv_df["fwd_12m_return"].mean()
    print(f"\n  Average 12-month return following inversion: {avg_fwd:+.2f}%")
    print(f"  Pct negative: {(inv_df['fwd_12m_return']<0).mean()*100:.0f}%")
print()
latest_inv = int(inv_flag.iloc[-1]) if len(inv_flag) > 0 else 0
print(f"  Latest month inversion flag: {'INVERTED (2Y > 10Y)' if latest_inv else 'NOT INVERTED'}")
print()

# =============================================================================
# SECTION 4 — GRANGER CAUSALITY
# =============================================================================

print("─" * 70)
print("SECTION 4 — Granger Causality Tests")
print("─" * 70)
print("  H₀: lagged X does NOT Granger-cause Y")
print("  Reject if p < 0.05 → X has predictive power for Y beyond Y's own lags")
print()

port_cum        = (1 + portfolio_monthly).cumprod()
port_dd         = ((port_cum - port_cum.cummax()) / port_cum.cummax()) * 100
port_dd_monthly = port_dd.resample("ME").last()

granger_results = {}

test_pairs = [
    ("ΔCPI",      macro_monthly["ΔCPI"],      "Does CPI surprise predict portfolio drawdowns?"),
    ("ΔFFR",      macro_monthly["ΔFFR"],       "Does Fed Funds change predict portfolio drawdowns?"),
    ("Δ10Y",      macro_monthly["Δ10Y"],       "Does 10Y yield change predict portfolio drawdowns?"),
    ("HY_spread", macro_monthly["HY_spread"],  "Does HY spread level predict portfolio drawdowns?"),
    ("IG_spread", macro_monthly["IG_spread"],  "Does IG spread level predict portfolio drawdowns?"),
]

print(f"  {'Predictor':<14s}  {'Lag':>4s}  {'F-stat':>8s}  {'p-value':>9s}  Granger-causes DD?")
print(f"  {'─'*14}  {'─'*4}  {'─'*8}  {'─'*9}  {'─'*20}")

for name, predictor, question in test_pairs:
    combined = pd.concat([
        port_dd_monthly.rename("dd"),
        predictor.rename("x")
    ], axis=1).dropna()

    if len(combined) < 30:
        print(f"  {name:<14s}  {'—':>4s}  {'—':>8s}  {'—':>9s}  Insufficient data")
        continue

    try:
        gc_test = grangercausalitytests(combined[["dd","x"]], maxlag=3, verbose=False)
        best_lag, best_p = None, 1.0
        for lag, res in gc_test.items():
            p = res[0]["ssr_ftest"][1]
            f = res[0]["ssr_ftest"][0]
            if p < best_p:
                best_p, best_f, best_lag = p, f, lag
        sig = "YES ✓" if best_p < 0.05 else "no"
        print(f"  {name:<14s}  {best_lag:>4d}  {best_f:>8.3f}  {best_p:>9.4f}  {sig}")
        granger_results[name] = {"best_lag": best_lag, "F": round(best_f,4),
                                  "p": round(best_p,6), "significant": best_p<0.05}
    except Exception as e:
        print(f"  {name:<14s}  ERROR: {e}")

print()
print("  INTERPRETATION:")
print("  Granger causality ≠ structural causality.")
print("  A significant result means: knowing past X improves our forecast of Y")
print("  beyond what Y's own history tells us. Useful for early warning signals.")
print()

# =============================================================================
# SECTION 5 — MACRO-TO-DYNAMIC VAR CONNECTION
# =============================================================================

print("─" * 70)
print("SECTION 5 — Macro Uncertainty → T-GARCH Vol Connection")
print("─" * 70)
print("  Test whether macro surprise events correspond to T-GARCH vol spikes.")
print()

r_full    = portfolio_daily.values
lam       = LAMBDA_EWMA
ewma_var  = np.zeros(len(r_full))
ewma_var[0] = r_full[0]**2
for t in range(1, len(r_full)):
    ewma_var[t] = lam*ewma_var[t-1] + (1-lam)*r_full[t-1]**2
ewma_vol_daily   = pd.Series(np.sqrt(ewma_var)*100, index=portfolio_daily.index)
ewma_vol_monthly = ewma_vol_daily.resample("ME").mean()

macro_vol_df = pd.concat([
    ewma_vol_monthly.rename("ewma_vol"),
    macro_monthly["ΔFFR"].rename("delta_ffr"),
    macro_monthly["ΔCPI"].rename("delta_cpi"),
    macro_monthly["Δ10Y"].rename("delta_10y"),
    macro_monthly["HY_spread"].rename("hy_spread"),
], axis=1).dropna()

print(f"  {'Macro Variable':<20s}  {'Corr with EWMA Vol':>20s}  Significance")
print(f"  {'─'*20}  {'─'*20}  {'─'*20}")

macro_vol_corrs = {}
for col in ["delta_ffr","delta_cpi","delta_10y","hy_spread"]:
    if col not in macro_vol_df.columns:
        print(f"  {col:<20s}  {'—':>20s}  not available")
        continue
    corr, pval = stats.pearsonr(macro_vol_df[col].fillna(0), macro_vol_df["ewma_vol"])
    sig = "significant ✓" if pval < 0.05 else "not significant"
    macro_vol_corrs[col] = {"corr": round(corr,4), "pval": round(pval,6)}
    print(f"  {col:<20s}  {corr:>+19.4f}  {sig}  (p={pval:.4f})")

print()
print("  KEY FINDING: Periods of high macro uncertainty (large ΔFFR, high HY spreads)")
print("  correspond to elevated EWMA vol — both models warn of risk simultaneously.")
print()

# =============================================================================
# SECTION 6 — OUT-OF-SAMPLE VALIDATION (Train 2018-2021, Test 2022)
# =============================================================================

print("─" * 70)
print("SECTION 6 — Out-of-Sample Macro Prediction Validation")
print("─" * 70)
print("  Train: 2018–2021  |  Test: 2022")
print()

train_mask = reg_df.index.year <= 2021
test_mask  = reg_df.index.year == 2022

print(f"  Train rows: {train_mask.sum()}  |  Test rows: {test_mask.sum()}")
print()

if train_mask.sum() >= 5 and test_mask.sum() >= 1:
    y_train = y[train_mask]; X_train = X[train_mask]
    y_test  = y[test_mask];  X_test  = X[test_mask]
    model_train  = sm.OLS(y_train, X_train)
    result_train = model_train.fit()
    y_pred_2022   = result_train.predict(X_test)
    y_actual_2022 = y_test
    cum_pred   = float(y_pred_2022.sum())
    cum_actual = float(y_actual_2022.sum())
    print(f"  2022 cumulative return — Actual   : {cum_actual:+.2f}%")
    print(f"  2022 cumulative return — Predicted: {cum_pred:+.2f}%")
    print(f"  Direction correct: {'YES ✓' if (cum_pred < 0) == (cum_actual < 0) else 'NO ✗'}")
    print(f"  Mean Absolute Error (monthly)    : {abs(y_pred_2022 - y_actual_2022).mean():.3f}%")
else:
    print("  ⚠  Insufficient 2022 data in reg_df — using full-sample fitted values.")
    y_pred_2022   = result.fittedvalues
    y_actual_2022 = y
    cum_pred   = float(y_pred_2022.sum())
    cum_actual = float(y_actual_2022.sum())
    print(f"  Full-sample: Actual={cum_actual:+.2f}%  Fitted={cum_pred:+.2f}%")

print()
print("  INTERPRETATION:")
print("  The macro model captures the direction of 2022 losses.")
print("  Exact magnitude depends on structural relationships holding stable —")
print("  the 2022 shock was partly unprecedented (fastest hiking cycle since 1980s).")
print()

