# ── PLOT 02: Macro Sensitivity Table ──────────────────────────────────────────
fig, ax = plt.subplots(figsize=(12, 5))
ax.axis("off")

shock_defs = {
    "Δ10Y +100bps"  : ("10Y Treasury yield rises 100bps", C_SPREAD),
    "ΔFFR +100bps"  : ("Fed Funds Rate rises 100bps",     C_SPREAD),
    "ΔCPI +1%"      : ("CPI rises 1% month-on-month",     C_CPI),
    "ΔIG +100bps"   : ("IG credit spread widens 100bps",  C_SPREAD),
    "Δ10Y -100bps"  : ("10Y Treasury yield falls 100bps", C_PORT),
    "ΔFFR -100bps"  : ("Fed Funds Rate falls 100bps",     C_PORT),
}

hdr  = ["Macro Shock", "Description", "Portfolio Impact (%)", "Direction"]
data = []
for shock, impact in sensitivity_table.items():
    desc, _ = shock_defs.get(shock, ("—", C_GREY))
    direction = "↓ Portfolio falls" if impact < 0 else "↑ Portfolio rises"
    data.append([shock, desc, f"{impact:+.3f}%", direction])

tbl = ax.table(cellText=data, colLabels=hdr, loc="center", cellLoc="center")
tbl.auto_set_font_size(False); tbl.set_fontsize(10); tbl.scale(1, 2.4)

for j in range(len(hdr)):
    tbl[0, j].set_facecolor(C_STEEL)
    tbl[0, j].set_text_props(color="white", fontweight="bold")

for i, (_, impact) in enumerate(sensitivity_table.items(), start=1):
    col = "#FDEDEC" if impact < 0 else "#EAFAF1"
    for j in range(len(hdr)):
        tbl[i, j].set_facecolor(col)
    tbl[i, 2].set_text_props(color=C_SPREAD if impact < 0 else C_PORT, fontweight="bold")

ax.set_title("Plot 02 — Macro Sensitivity Table  (CIO Deliverable)\n"
             "Estimated portfolio impact per macro shock · Based on OLS regression",
             fontsize=TFS, fontweight="bold", pad=20)
plt.tight_layout()
plt.savefig("plots/phase4_02_sensitivity_table.png", dpi=150, bbox_inches="tight")
plt.show(); plt.close()

# ── PLOT 03: OLS Coefficients with Confidence Intervals ───────────────────────
fig, ax = plt.subplots(figsize=(11, 5))

coef_names = [c for c in result.params.index if c != "const"]
coef_vals  = result.params[coef_names].values
coef_errs  = result.bse[coef_names].values * 1.96
pvals      = result.pvalues[coef_names].values
bar_cols   = [C_SPREAD if v < 0 else C_PORT for v in coef_vals]
sig_alpha  = [1.0 if p < 0.05 else 0.45 for p in pvals]

x_pos = np.arange(len(coef_names))
for i, (val, err, col, alpha) in enumerate(zip(coef_vals, coef_errs, bar_cols, sig_alpha)):
    ax.bar(i, val, color=col, alpha=alpha, edgecolor="white", width=0.55, zorder=3)
    ax.errorbar(i, val, yerr=err, fmt="none", color=C_STEEL, capsize=5,
                capthick=1.5, elinewidth=1.5, zorder=4)
    star = "**" if pvals[i] < 0.01 else "*" if pvals[i] < 0.05 else ""
    ax.text(i, val + (err + 0.01 if val >= 0 else -err - 0.015),
            f"{star}\np={pvals[i]:.3f}", ha="center",
            va="bottom" if val >= 0 else "top", fontsize=8, color=C_STEEL)

ax.axhline(0, color=C_STEEL, lw=0.9, ls="--")
ax.set_xticks(x_pos)
ax.set_xticklabels(coef_names, fontsize=11)
ax.set_title("Plot 03 — OLS Regression Coefficients  (HAC Standard Errors)\n"
             "Error bars = 95% CI  ·  Faded = not significant at 5%  ·  ** p<0.01  * p<0.05",
             fontsize=TFS, fontweight="bold")
clean_ax(ax, ylabel="Coefficient (effect on monthly return %)")
ax.yaxis.grid(True, alpha=0.22); ax.set_axisbelow(True)
plt.tight_layout()
plt.savefig("plots/phase4_03_ols_coefficients.png", dpi=150, bbox_inches="tight")
plt.show(); plt.close()

