print("  Rendering I5 — Liquidity Scorecard Heatmap …")

# Normalise 3 metrics to 0-100 (0=most liquid, 100=least liquid)
def normalise(s):
    mn, mx = s.min(), s.max()
    if mx == mn: return pd.Series(50, index=s.index)
    return (s - mn) / (mx - mn) * 100

dtl_norm  = normalise(liq_df["days_to_liq"])
pct_norm  = normalise(liq_df["pct_of_adv"])
cs_norm_v = normalise(cs_latest.reindex(liq_df.index).fillna(cs_latest.mean()) * 10000)

score_df = pd.DataFrame({
    "Days to Liquidate" : dtl_norm,
    "% of ADV"          : pct_norm,
    "Roll Spread"        : cs_norm_v,
}, index=liq_df.index)

composite = score_df.mean(axis=1).sort_values(ascending=False)
score_df  = score_df.loc[composite.index]

fig_i5 = go.Figure(data=go.Heatmap(
    z=score_df.values.T,
    x=score_df.index.tolist(),
    y=score_df.columns.tolist(),
    colorscale=[[0,"#EAFAF1"],[0.5,"#F9E79F"],[1.0,"#FADBD8"]],
    zmin=0, zmax=100,
    text=score_df.values.T.round(1),
    texttemplate="%{text:.0f}",
    textfont=dict(size=10, color="#1C2833"),
    colorbar=dict(title="Score<br>(0=liquid,<br>100=illiquid)", thickness=14,
                  titlefont=dict(size=11))
))
layout_i5 = playout("I5 — Liquidity Scorecard Heatmap  (0 = most liquid, 100 = least liquid)",
                    "Composite of days-to-liquidate, % of ADV, and estimated spread · Red = least liquid",
                    height=500)
