fig_i5.update_layout(
    **layout_i5,
    xaxis=dict(tickangle=45, tickfont=dict(size=10), side="bottom",
               tickmode="array", tickvals=score_df.index.tolist(),
               ticktext=score_df.index.tolist()),
    yaxis=dict(tickfont=dict(size=11)),
    width=900,
)
