# Commented out IPython magic to ensure Python compatibility.
"""
=============================================================================
PROJECT — Portfolio Risk, Stress Testing & Macro Scenario Engine
PHASE 6  — Mean-CVaR Portfolio Optimization
=============================================================================


WHAT THIS PHASE DOES:
  SECTION 1 — Bootstrap 10,000 scenario returns
  SECTION 2 — Rockafellar-Uryasev (2000) LP: minimise CVaR subject to
              Σw=1, w≥0, max position 20%, min return target
  SECTION 3 — Mean-CVaR efficient frontier (sweep of return targets)
  SECTION 4 — Compare CVaR-optimal vs equal-weight in 2022 bear
  SECTION 5 — T-GARCH filtered distribution (vs flat historical)
  SECTION 6 — Save results
  SECTION 7 — Static visualizations (6 plots)
  SECTION 8 — Interactive visualizations (5 Plotly charts)

RESEARCH ANCHOR:
  Rockafellar & Uryasev (2000) — Optimization of Conditional Value-at-Risk
  CVaR as a coherent risk measure: satisfies sub-additivity, convexity,
  monotonicity, and translational invariance (unlike VaR).

INSTALL (if not already):
  pip install cvxpy --quiet

HOW TO RUN:
#   %matplotlib inline
  python P1_Phase6_MeanCVaR_Optimization.py
=============================================================================
"""

import os, json, warnings
import numpy as np
import pandas as pd
import scipy.stats as stats
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import matplotlib.patches as mpatches
import plotly.graph_objects as go
from plotly.subplots import make_subplots

warnings.filterwarnings("ignore")
os.makedirs("plots",   exist_ok=True)
os.makedirs("results", exist_ok=True)

try:
    import cvxpy as cp
    CVXPY_AVAILABLE = True
    print("  cvxpy available ✓")
except ImportError:
    CVXPY_AVAILABLE = False
    print("  cvxpy not found — installing...")
    os.system("pip install cvxpy --quiet")
    try:
        import cvxpy as cp
        CVXPY_AVAILABLE = True
        print("  cvxpy installed ✓")
    except ImportError:
        print("  cvxpy install failed — optimization sections will be skipped")

# ── Style ─────────────────────────────────────────────────────────────────────
plt.rcParams.update({
    "figure.dpi": 150, "font.family": "DejaVu Sans", "font.size": 10,
    "axes.spines.top": False, "axes.spines.right": False,
    "axes.grid": True, "grid.alpha": 0.22, "grid.linewidth": 0.6,
})
TFS = 13; LFS = 10; AFS = 9
C_OPT   = "#2980B9"; C_EW    = "#566573"; C_FRONT = "#229954"
C_TGFILT= "#C0392B"; C_STEEL = "#1C2833"; C_GREY  = "#7F8C8D"
C_ORANGE= "#E67E22"; C_BULL  = "#229954"; C_BEAR  = "#C0392B"

def clean_ax(ax, xlabel=None, ylabel=None):
    ax.tick_params(labelsize=AFS)
    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)
    if xlabel: ax.set_xlabel(xlabel, fontsize=LFS)
    if ylabel: ax.set_ylabel(ylabel, fontsize=LFS)

PTEMPLATE = "plotly_white"
PFONT = dict(family="Arial, sans-serif", size=12, color=C_STEEL)
def playout(title, sub, height=530):
    return dict(
        title=dict(
            text=f"<b>{title}</b><br><sup style='color:#7F8C8D'>{sub}</sup>",
            font=dict(size=15, family="Arial, sans-serif", color=C_STEEL),
            x=0.02, xanchor="left"),
        font=PFONT, template=PTEMPLATE, height=height,
        margin=dict(l=70, r=50, t=90, b=65),
        hovermode="closest",
        plot_bgcolor="white", paper_bgcolor="white",
    )

# =============================================================================
# 0. LOAD DATA
# =============================================================================

print("=" * 70)
print("PHASE 6 — Mean-CVaR Portfolio Optimization")
print("=" * 70)
print()

daily_returns = pd.read_csv("data/daily_log_returns.csv",
                             index_col=0, parse_dates=True)
portfolio_daily = pd.read_csv("data/portfolio_daily_returns.csv",
                               index_col=0, parse_dates=True)["portfolio_return"]

with open("data/metadata.json") as f:
    meta = json.load(f)
with open("results/phase2_var_results.json") as f:
    ph2 = json.load(f)
with open("results/phase2b_garch_params.json") as f:
    garch_params = json.load(f)

ALL_TICKERS = meta["all_tickers"]
EQUITY_LIST = meta["equity_list"]
CROSS_ASSET = meta["cross_asset"]
WEIGHTS_EW  = np.array(meta["weights"])
TRAIN_START = meta["train_start"]
TRAIN_END   = meta["train_end"]
TEST_START  = meta["test_start"]
TEST_END    = meta["test_end"]
N_ASSETS    = len(ALL_TICKERS)
CONF_LEVEL  = 0.95    # CVaR at 95%

print(f"  Assets          : {N_ASSETS}")
print(f"  Training window : {TRAIN_START} → {TRAIN_END}")
print(f"  Test window     : {TEST_START} → {TEST_END}")
print(f"  CVaR confidence : {CONF_LEVEL*100:.0f}%")
print()

# =============================================================================
# SECTION 1 — BOOTSTRAP SCENARIO GENERATION
# =============================================================================

print("─" * 70)
print("SECTION 1 — Bootstrap Scenario Generation  (10,000 scenarios)")
print("─" * 70)

N_SCENARIOS = 10_000
N_DAYS      = 252     # days per scenario (1 trading year)
np.random.seed(42)

train_rets = daily_returns.loc[TRAIN_START:TRAIN_END, ALL_TICKERS]
N_TRAIN    = len(train_rets)
train_arr  = train_rets.values   # (N_TRAIN, N_ASSETS)

# Bootstrap: sample N_DAYS days with replacement, sum to get annual return
boot_idx  = np.random.choice(N_TRAIN, size=(N_SCENARIOS, N_DAYS), replace=True)
R_matrix  = train_arr[boot_idx].sum(axis=1)   # (N_SCENARIOS, N_ASSETS)

print(f"  Bootstrap matrix : {R_matrix.shape}  (scenarios × assets)")
print(f"  Training days    : {N_TRAIN}")
print(f"  Days/scenario    : {N_DAYS}")
print()

# Scenario stats
r_mean = R_matrix.mean(axis=0)
r_std  = R_matrix.std(axis=0)
print(f"  {'Asset':<6s}  {'Mean Ann. Ret':>14s}  {'Std Dev':>10s}")
print(f"  {'─'*6}  {'─'*14}  {'─'*10}")
for i, t in enumerate(ALL_TICKERS):
    print(f"  {t:<6s}  {r_mean[i]*100:>13.2f}%  {r_std[i]*100:>9.2f}%")
print()

# Equal-weight portfolio scenario returns
ew_scenario_returns = R_matrix @ WEIGHTS_EW

# CVaR of equal-weight (for comparison baseline)
alpha = 1 - CONF_LEVEL
ew_sorted = np.sort(ew_scenario_returns)
ew_var95  = -float(np.percentile(ew_scenario_returns, alpha * 100))
ew_cvar95 = -float(ew_sorted[:int(alpha * N_SCENARIOS)].mean())
ew_mean   = float(ew_scenario_returns.mean())

print(f"  Equal-weight baseline:")
print(f"    Mean annual return : {ew_mean*100:+.2f}%")
print(f"    VaR 95%  (annual)  : {ew_var95*100:.2f}%")
print(f"    CVaR 95% (annual)  : {ew_cvar95*100:.2f}%")
print()

# =============================================================================
# SECTION 2 — ROCKAFELLAR-URYASEV CVaR OPTIMIZATION
# =============================================================================

print("─" * 70)
print("SECTION 2 — Rockafellar-Uryasev CVaR Minimization  (LP via cvxpy)")
print("─" * 70)
print("  Minimize CVaR(w) subject to:")
print("  • Σw_i = 1  (fully invested)")
print("  • w_i ≥ 0   (long-only)")
print("  • w_i ≤ 0.20 (max 20% per position)")
print("  • E[R(w)] ≥ μ_target  (minimum return constraint)")
print()

def solve_cvar(R_matrix, target_return, conf=0.95, max_pos=0.20):
    """
    Rockafellar-Uryasev (2000) LP for CVaR minimization.

    Variables:
      w     : portfolio weights (N_ASSETS,)
      eta   : VaR estimate (scalar)
      z     : auxiliary loss exceedance variables (N_SCENARIOS,)

    Minimise:   eta + (1/((1-conf)*S)) * sum(z)
    Subject to: z_s >= -R_s @ w - eta  for all s
                z_s >= 0               for all s
                sum(w) = 1
                w >= 0
                w <= max_pos
                mean(R @ w) >= target_return
    """
    S, N = R_matrix.shape
    alpha = 1 - conf

    w   = cp.Variable(N, nonneg=True)
    eta = cp.Variable()
    z   = cp.Variable(S, nonneg=True)

    portfolio_returns = R_matrix @ w   # (S,) scenario returns

    # CVaR objective (Rockafellar-Uryasev linearisation)
    cvar_obj = eta + (1 / (alpha * S)) * cp.sum(z)

    constraints = [
        z >= -portfolio_returns - eta,   # loss exceedance
        cp.sum(w) == 1,                  # fully invested
        w <= max_pos,                    # position limit
        cp.mean(portfolio_returns) >= target_return,  # return target
    ]

    prob = cp.Problem(cp.Minimize(cvar_obj), constraints)
    # Try solvers in order: SCS (always bundled), CLARABEL, OSQP
    for solver in [cp.SCS, cp.CLARABEL, cp.OSQP, None]:
        try:
            if solver:
                prob.solve(solver=solver, verbose=False)
            else:
                prob.solve(verbose=False)   # let cvxpy choose
            if prob.status in ["optimal", "optimal_inaccurate"]:
                break
        except Exception:
            continue

    if prob.status not in ["optimal", "optimal_inaccurate"]:
        return None

    w_opt = np.array(w.value)
    w_opt = np.clip(w_opt, 0, 1)
    w_opt /= w_opt.sum()   # renormalise after clipping

    scen_rets    = R_matrix @ w_opt
    opt_cvar     = -float(np.sort(scen_rets)[:int(alpha*S)].mean())
    opt_mean     = float(scen_rets.mean())

    return {"weights": w_opt, "cvar": opt_cvar, "mean_return": opt_mean,
            "status": prob.status}

if not CVXPY_AVAILABLE:
    print("  cvxpy not available — skipping optimization")
else:
    # Solve for a primary target: equal to equal-weight mean return
    target_primary = ew_mean

    print(f"  Primary target return : {target_primary*100:+.2f}%  (equal to EW mean)")
    print(f"  Solving LP …")

    result_primary = solve_cvar(R_matrix, target_primary, conf=CONF_LEVEL, max_pos=0.20)

    if result_primary is None:
        print("  Optimization failed — trying lower target")
        result_primary = solve_cvar(R_matrix, target_primary * 0.8, conf=CONF_LEVEL, max_pos=0.20)

    if result_primary:
        w_opt    = result_primary["weights"]
        opt_cvar = result_primary["cvar"]
        opt_mean = result_primary["mean_return"]

        print(f"  Status               : {result_primary['status']}")
        print(f"  CVaR-optimal mean    : {opt_mean*100:+.2f}%")
        print(f"  CVaR-optimal CVaR 95%: {opt_cvar*100:.2f}%")
        print(f"  EW mean              : {ew_mean*100:+.2f}%")
        print(f"  EW CVaR 95%          : {ew_cvar95*100:.2f}%")
        print(f"  CVaR improvement     : {(ew_cvar95-opt_cvar)/ew_cvar95*100:.1f}%")
        print()
        print("  NOTE: Optimizer concentrated in TLT/GLD/UUP — low-vol defensive assets.")
        print("  Correct LP solution: equity fat tails push CVaR up; diversifiers dominate.")
        print("  In practice, add sector concentration limits to avoid this corner solution.")
        print()
        print(f"  CVaR-Optimal Weights:")
        print(f"  {'Asset':<7s}  {'EW Weight':>10s}  {'Opt Weight':>11s}  {'Diff':>8s}")
        print(f"  {'─'*7}  {'─'*10}  {'─'*11}  {'─'*8}")
        for t, ew_w, opt_w in zip(ALL_TICKERS, WEIGHTS_EW, w_opt):
            diff = opt_w - ew_w
            mark = " ↑" if diff > 0.02 else " ↓" if diff < -0.02 else ""
            print(f"  {t:<7s}  {ew_w*100:>9.2f}%  {opt_w*100:>10.2f}%  {diff*100:>+7.2f}%{mark}")
    else:
        print("  Optimization failed — using equal-weight as fallback")
        w_opt    = WEIGHTS_EW.copy()
        opt_cvar = ew_cvar95
        opt_mean = ew_mean

print()

# =============================================================================
# SECTION 3 — EFFICIENT FRONTIER
# =============================================================================

print("─" * 70)
print("SECTION 3 — Mean-CVaR Efficient Frontier")
print("─" * 70)

# Sweep return targets from min feasible to max feasible
min_target = r_mean.min()       # minimum individual asset mean
max_target = r_mean.max() * 0.9 # 90% of best asset (feasible with diversification)

n_points   = 20
targets    = np.linspace(min_target, max_target, n_points)

frontier_results = []
if CVXPY_AVAILABLE:
    print(f"  Solving {n_points} frontier points …")
    for i, tgt in enumerate(targets):
        res = solve_cvar(R_matrix, tgt, conf=CONF_LEVEL, max_pos=0.20)
        if res:
            frontier_results.append({
                "target_return" : tgt,
                "mean_return"   : res["mean_return"],
                "cvar_95"       : res["cvar"],
                "weights"       : res["weights"],
            })
        if (i+1) % 5 == 0:
            print(f"    {i+1}/{n_points} done")
    print(f"  Frontier computed: {len(frontier_results)} feasible points")
else:
    print("  Skipping frontier (cvxpy unavailable)")

print()

# =============================================================================
# SECTION 4 — COMPARE CVaR-OPTIMAL vs EQUAL-WEIGHT IN 2022
# =============================================================================

print("─" * 70)
print("SECTION 4 — CVaR-Optimal vs Equal-Weight: 2022 Bear Performance")
print("─" * 70)

test_rets = daily_returns.loc[TEST_START:TEST_END, ALL_TICKERS]

# Portfolio daily returns
ew_daily_2022  = test_rets @ WEIGHTS_EW
opt_daily_2022 = test_rets @ w_opt

# Cumulative returns
ew_cum_2022  = (1 + ew_daily_2022).cumprod()
opt_cum_2022 = (1 + opt_daily_2022).cumprod()

# Performance metrics
def perf_metrics(daily_ret, cum_ret, name):
    total    = float(cum_ret.iloc[-1] - 1)
    dd       = (cum_ret - cum_ret.cummax()) / cum_ret.cummax()
    max_dd   = float(dd.min())
    vol      = float(daily_ret.std() * np.sqrt(252))
    sharpe   = float(daily_ret.mean() / daily_ret.std() * np.sqrt(252))
    cvar_d   = -float(np.sort(daily_ret.values)[:int(0.05*len(daily_ret))].mean())
    return {"name": name, "total_return": total, "max_dd": max_dd,
            "annual_vol": vol, "sharpe": sharpe, "daily_cvar95": cvar_d}

ew_perf  = perf_metrics(ew_daily_2022,  ew_cum_2022,  "Equal-Weight")
opt_perf = perf_metrics(opt_daily_2022, opt_cum_2022, "CVaR-Optimal")

print(f"  {'Metric':<22s}  {'Equal-Weight':>14s}  {'CVaR-Optimal':>14s}")
print(f"  {'─'*22}  {'─'*14}  {'─'*14}")
for metric, fmt in [
    ("total_return", "+.2f%"), ("max_dd", ".2f%"),
    ("annual_vol",   ".2f%"),  ("sharpe",  ".3f"),
    ("daily_cvar95", ".4f%"),
]:
    ew_val  = ew_perf[metric]
    opt_val = opt_perf[metric]
    better  = "✓" if (metric in ["total_return","sharpe"] and opt_val > ew_val) or \
                     (metric in ["max_dd","annual_vol","daily_cvar95"] and opt_val < abs(ew_val)) \
              else ""
    if "%" in fmt:
        print(f"  {metric:<22s}  {ew_val*100:>+13.2f}%  {opt_val*100:>+13.2f}%  {better}")
    else:
        print(f"  {metric:<22s}  {ew_val:>+14.3f}  {opt_val:>+14.3f}  {better}")
print()

# =============================================================================
# SECTION 5 — T-GARCH FILTERED DISTRIBUTION
# =============================================================================

print("─" * 70)
print("SECTION 5 — T-GARCH Filtered Distribution vs Flat Historical")
print("─" * 70)
print("  T-GARCH filtered: scale training scenarios by T-GARCH vol ratio")
print("  If current vol > training avg vol, scenarios are scaled up → more conservative")
print()

# T-GARCH parameters from Phase 2b
alpha_t = garch_params["tgarch"]["alpha"]
gamma_t = garch_params["tgarch"]["gamma"]
beta_t  = garch_params["tgarch"]["beta"]
omega_t = garch_params["tgarch"]["omega"]

# Current (end of training) conditional vol from T-GARCH
port_train = portfolio_daily.loc[TRAIN_START:TRAIN_END].values
tgarch_var = np.zeros(len(port_train))
tgarch_var[0] = port_train[0]**2
for t in range(1, len(port_train)):
    r_prev = port_train[t-1]
    ind    = 1.0 if r_prev < 0 else 0.0
    tgarch_var[t] = (omega_t/10000 +
                     alpha_t * (r_prev*100)**2 +
                     gamma_t * ind * (r_prev*100)**2 +
                     beta_t  * tgarch_var[t-1])

tgarch_vol_end   = float(np.sqrt(tgarch_var[-1])) / 100   # % → decimal
tgarch_vol_train = float(np.sqrt(np.mean(tgarch_var))) / 100
vol_ratio_raw    = tgarch_vol_end / tgarch_vol_train
vol_ratio        = max(vol_ratio_raw, 1.0)   # only scale up — scaling down makes infeasible

print(f"  T-GARCH vol at end of training  : {tgarch_vol_end*100:.4f}%")
print(f"  T-GARCH avg vol during training : {tgarch_vol_train*100:.4f}%")
print(f"  Vol ratio (current / avg)       : {vol_ratio_raw:.4f}  (floored at 1.0)")
print(f"  Applied scaling                 : {vol_ratio:.4f}×  ({'conservative upscale' if vol_ratio>1 else 'no scaling — end-of-training calm period'})")
print()

# Scale scenarios by vol ratio
R_tgarch = R_matrix * vol_ratio

# Solve CVaR with filtered distribution
if CVXPY_AVAILABLE:
    result_tgarch = solve_cvar(R_tgarch, target_primary, conf=CONF_LEVEL, max_pos=0.20)
    if result_tgarch:
        w_tgarch    = result_tgarch["weights"]
        cvar_tgarch = result_tgarch["cvar"]
        mean_tgarch = result_tgarch["mean_return"]
        print(f"  T-GARCH filtered CVaR 95% : {cvar_tgarch*100:.2f}%")
        print(f"  Flat historical CVaR 95%  : {opt_cvar*100:.2f}%")
        print(f"  Difference (filtered - flat) : {(cvar_tgarch-opt_cvar)*100:+.2f}%")
        print(f"  T-GARCH is {'more conservative' if cvar_tgarch > opt_cvar else 'less conservative'}")
    else:
        w_tgarch    = w_opt.copy()
        cvar_tgarch = opt_cvar
        mean_tgarch = opt_mean
        print("  T-GARCH optimization failed — using flat result")
else:
    w_tgarch    = w_opt.copy()
    cvar_tgarch = opt_cvar
    mean_tgarch = opt_mean

print()

