# Commented out IPython magic to ensure Python compatibility.
"""
=============================================================================
PROJECT — Portfolio Risk, Stress Testing & Macro Scenario Engine
PHASE 7  — SQL Automated Risk Reporting
=============================================================================


WHAT THIS PHASE DOES:
  SECTION 1 — Build SQLite database from all prior phase outputs
              Tables: daily_risk_metrics, var_backtest, macro_signals,
                      stress_scenarios, liquidity_metrics, optimal_weights
  SECTION 2 — SQL window functions: rolling breach rates, VaR premium
              Rolling 21-day breach rate per model
              Dynamic VaR premium (T-GARCH vs Static)
              Monthly vol regime classification
  SECTION 3 — Automated risk report queries
              Kupiec summary query
              Macro sensitivity lookup
              Stress scenario comparison
              Liquidity violation alert query
  SECTION 4 — Save database and query results
  SECTION 5 — Static visualizations (5 plots)
  SECTION 6 — Interactive visualizations (3 Plotly charts)

HOW TO RUN:
#   %matplotlib inline
  python P1_Phase7_SQL_Reporting.py
=============================================================================
"""

import os, json, sqlite3, warnings
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import plotly.graph_objects as go
from plotly.subplots import make_subplots

warnings.filterwarnings("ignore")
os.makedirs("results", exist_ok=True)
os.makedirs("plots",   exist_ok=True)

# ── Style ─────────────────────────────────────────────────────────────────────
plt.rcParams.update({
    "figure.dpi": 150, "font.family": "DejaVu Sans", "font.size": 10,
    "axes.spines.top": False, "axes.spines.right": False,
    "axes.grid": True, "grid.alpha": 0.22, "grid.linewidth": 0.6,
})
TFS = 13; LFS = 10; AFS = 9
C_STATIC = "#566573"; C_EWMA  = "#2980B9"; C_GARCH = "#229954"
C_TGARCH = "#C0392B"; C_STEEL = "#1C2833"; C_GREY  = "#7F8C8D"
C_ORANGE = "#E67E22"; C_OK    = "#229954"; C_ALERT = "#C0392B"

def clean_ax(ax, xlabel=None, ylabel=None):
    ax.tick_params(labelsize=AFS)
    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)
    if xlabel: ax.set_xlabel(xlabel, fontsize=LFS)
    if ylabel: ax.set_ylabel(ylabel, fontsize=LFS)

PTEMPLATE = "plotly_white"
PFONT = dict(family="Arial, sans-serif", size=12, color=C_STEEL)
def playout(title, sub, height=520):
    return dict(
        title=dict(
            text=f"<b>{title}</b><br><sup style='color:#7F8C8D'>{sub}</sup>",
            font=dict(size=15, family="Arial, sans-serif", color=C_STEEL),
            x=0.02, xanchor="left"),
        font=PFONT, template=PTEMPLATE, height=height,
        margin=dict(l=70, r=50, t=90, b=65),
        hovermode="x unified",
        plot_bgcolor="white", paper_bgcolor="white",
    )

# =============================================================================
# 0. LOAD ALL PRIOR OUTPUTS
# =============================================================================

print("=" * 70)
print("PHASE 7 — SQL Automated Risk Reporting")
print("=" * 70)
print()

# Phase 2b VaR time series
var_ts = pd.read_csv("results/phase2b_var_timeseries_2022.csv",
                      index_col=0, parse_dates=True)

# Phase 2b Kupiec results
kupiec_df = pd.read_csv("results/phase2b_kupiec_results.csv", index_col=0)

# Phase 3 scenario results
with open("results/phase3_scenario_results.json") as f:
    ph3 = json.load(f)

# Phase 4 OLS results
with open("results/phase4_ols_results.json") as f:
    ph4 = json.load(f)

macro_monthly = pd.read_csv("results/phase4_macro_portfolio_monthly.csv",
                             index_col=0, parse_dates=True)

# Phase 5 liquidity
liq_df   = pd.read_csv("results/phase5_liquidity_metrics.csv", index_col=0)
stress_df = pd.read_csv("results/phase5_stress_exit_costs.csv", index_col=0)
with open("results/phase5_liquidity_summary.json") as f:
    ph5 = json.load(f)

# Phase 6 weights & performance
weights_df = pd.read_csv("results/phase6_optimal_weights.csv", index_col=0)
with open("results/phase6_summary.json") as f:
    ph6 = json.load(f)

# Portfolio daily returns (for EWMA vol)
port_daily = pd.read_csv("data/portfolio_daily_returns.csv",
                          index_col=0, parse_dates=True)["portfolio_return"]
with open("data/metadata.json") as f:
    meta = json.load(f)

ALL_TICKERS  = meta["all_tickers"]
LAMBDA_EWMA  = meta["lambda_ewma"]
STATIC_VAR95 = float(var_ts["var95_static"].iloc[0])

print("  All prior phase outputs loaded successfully.")
print(f"  VaR time series  : {len(var_ts)} daily observations (2022)")
print(f"  Macro monthly    : {len(macro_monthly)} observations")
print(f"  Liquidity assets : {len(liq_df)}")
print()

# =============================================================================
# SECTION 1 — BUILD SQLITE DATABASE
# =============================================================================

print("─" * 70)
print("SECTION 1 — Building SQLite Database")
print("─" * 70)

DB_PATH = "results/portfolio_risk.db"
if os.path.exists(DB_PATH):
    os.remove(DB_PATH)

conn = sqlite3.connect(DB_PATH)
cur  = conn.cursor()

# ── Table 1: daily_risk_metrics ───────────────────────────────────────────────
cur.execute("""
CREATE TABLE daily_risk_metrics (
    date          TEXT PRIMARY KEY,
    actual_return REAL,
    actual_loss   REAL,
    var95_static  REAL,
    var95_ewma    REAL,
    var95_garch   REAL,
    var95_tgarch  REAL,
    breach_static INTEGER,
    breach_ewma   INTEGER,
    breach_garch  INTEGER,
    breach_tgarch INTEGER,
    ewma_vol      REAL
)
""")

# Compute EWMA vol series for 2022
r_full   = port_daily.values
ewma_var = np.zeros(len(r_full))
ewma_var[0] = r_full[0]**2
for t in range(1, len(r_full)):
    ewma_var[t] = LAMBDA_EWMA*ewma_var[t-1] + (1-LAMBDA_EWMA)*r_full[t-1]**2
ewma_vol_full = pd.Series(np.sqrt(ewma_var)*100, index=port_daily.index)
ewma_vol_2022 = ewma_vol_full.reindex(var_ts.index)

rows_daily = []
for date, row in var_ts.iterrows():
    rows_daily.append((
        str(date.date()),
        round(float(row["actual_return"]), 8),
        round(float(row["actual_loss"]),   8),
        round(float(row["var95_static"]),  8),
        round(float(row["var95_ewma"]),    8),
        round(float(row["var95_garch"]),   8),
        round(float(row["var95_tgarch"]),  8),
        int(row["breach_static"]),
        int(row["breach_ewma"]),
        int(row["breach_garch"]),
        int(row["breach_tgarch"]),
        round(float(ewma_vol_2022.get(date, 0)), 6),
    ))

cur.executemany("""
INSERT INTO daily_risk_metrics VALUES (?,?,?,?,?,?,?,?,?,?,?,?)
""", rows_daily)
print(f"  daily_risk_metrics : {len(rows_daily)} rows inserted")

# ── Table 2: var_backtest ─────────────────────────────────────────────────────
cur.execute("""
CREATE TABLE var_backtest (
    model         TEXT PRIMARY KEY,
    n_breaches    INTEGER,
    breach_rate   REAL,
    kupiec_lr     REAL,
    kupiec_pvalue REAL,
    pass_fail     TEXT,
    vol_dynamics  TEXT
)
""")

vol_dynamics_map = {
    "Static HS-VaR" : "Fixed historical window",
    "FHS-EWMA"      : "EWMA λ=0.94, no mean reversion",
    "FHS-GARCH"     : "Symmetric GARCH, mean-reverting",
    "FHS-T-GARCH"   : "Asymmetric GJR-GARCH, leverage effect",
}
for model, row in kupiec_df.iterrows():
    cur.execute("""
INSERT INTO var_backtest VALUES (?,?,?,?,?,?,?)
""", (model, int(row["n_breaches"]), float(row["breach_rate"]),
      float(row["LR_stat"]), float(row["p_value"]),
      "PASS" if row["pass"] else "FAIL",
      vol_dynamics_map.get(model, "—")))
print(f"  var_backtest       : {len(kupiec_df)} rows inserted")

# ── Table 3: macro_signals ────────────────────────────────────────────────────
cur.execute("""
CREATE TABLE macro_signals (
    month           TEXT PRIMARY KEY,
    port_return     REAL,
    delta_ffr       REAL,
    delta_cpi       REAL,
    delta_10y       REAL,
    delta_ig_spread REAL,
    ols_fitted      REAL,
    inversion_flag  INTEGER
)
""")

# Compute OLS fitted values
from sklearn.linear_model import LinearRegression
X_cols = ["ΔFFR","ΔCPI","Δ10Y","ΔIG_spread"]
avail  = [c for c in X_cols if c in macro_monthly.columns]
if avail and "port_return" in macro_monthly.columns:
    X = macro_monthly[avail].values
    y = macro_monthly["port_return"].values * 100
    # Simple prediction using stored coefficients
    coefs  = ph4["coefficients"]
    fitted = (coefs.get("const", 0) +
              sum(coefs.get(c, 0) * macro_monthly[c].values
                  for c in avail if c in coefs))
    fitted_s = pd.Series(fitted, index=macro_monthly.index)
else:
    fitted_s = pd.Series(0.0, index=macro_monthly.index)

rows_macro = []
for date, row in macro_monthly.iterrows():
    rows_macro.append((
        str(date.to_period("M")),
        round(float(row.get("port_return", 0)) * 100, 6),
        round(float(row.get("ΔFFR",       0)), 6),
        round(float(row.get("ΔCPI",       0)), 6),
        round(float(row.get("Δ10Y",       0)), 6),
        round(float(row.get("ΔIG_spread", 0)), 6),
        round(float(fitted_s.get(date, 0)), 6),
        int(row.get("INVERSION", 0) or 0),
    ))

cur.executemany("""
INSERT OR IGNORE INTO macro_signals VALUES (?,?,?,?,?,?,?,?)
""", rows_macro)
print(f"  macro_signals      : {len(rows_macro)} rows inserted")

# ── Table 4: stress_scenarios ─────────────────────────────────────────────────
cur.execute("""
CREATE TABLE stress_scenarios (
    scenario_name   TEXT PRIMARY KEY,
    equity_shock    REAL,
    rate_shock_bps  REAL,
    portfolio_pnl   REAL,
    pnl_vs_var      REAL,
    tlt_contribution REAL,
    gld_contribution REAL,
    scenario_type   TEXT
)
""")

scenario_rows = [
    ("Bear",         -0.30,  200, -25.67, 17.0, -1.111, 0.278, "forward"),
    ("Base",          0.08,    0,   6.94, -4.6,  0.111, 0.167, "forward"),
    ("Bull",          0.20,  -50,  17.22,-11.4,  0.444, 0.222, "forward"),
    ("COVID_Replay", None,  None, -18.81, 12.5,-16.45,-12.71, "historical"),
    ("2022_Replay",  None,   237, -11.18,  7.4,-16.45,-12.71, "historical"),
]
cur.executemany("""
INSERT INTO stress_scenarios VALUES (?,?,?,?,?,?,?,?)
""", scenario_rows)
print(f"  stress_scenarios   : {len(scenario_rows)} rows inserted")

# ── Table 5: liquidity_metrics ────────────────────────────────────────────────
cur.execute("""
CREATE TABLE liquidity_metrics (
    ticker          TEXT PRIMARY KEY,
    position_usd    REAL,
    adv_proxy_usd   REAL,
    days_to_liq     REAL,
    pct_of_adv      REAL,
    roll_spread_bps REAL,
    stress_exit_cost REAL,
    adv_violation   INTEGER
)
""")

rows_liq = []
for ticker, row in liq_df.iterrows():
    stress_cost = float(stress_df.loc[ticker, "stress_exit_cost"]) if ticker in stress_df.index else 0
    spread_bps  = float(stress_df.loc[ticker, "normal_spread_bps"]) if ticker in stress_df.index else 0
    rows_liq.append((
        ticker,
        round(float(row["position_$M"]) * 1e6, 2),
        round(float(row["adv_proxy_$M"]) * 1e6, 2),
        round(float(row["days_to_liq"]), 4),
        round(float(row["pct_of_adv"]), 4),
        round(spread_bps, 4),
        round(stress_cost, 2),
        1 if float(row["pct_of_adv"]) > 10.0 else 0,
    ))

cur.executemany("""
INSERT INTO liquidity_metrics VALUES (?,?,?,?,?,?,?,?)
""", rows_liq)
print(f"  liquidity_metrics  : {len(rows_liq)} rows inserted")

# ── Table 6: optimal_weights ──────────────────────────────────────────────────
cur.execute("""
CREATE TABLE optimal_weights (
    ticker        TEXT PRIMARY KEY,
    ew_weight     REAL,
    opt_weight    REAL,
    tgarch_weight REAL,
    weight_diff   REAL
)
""")

for ticker, row in weights_df.iterrows():
    cur.execute("INSERT INTO optimal_weights VALUES (?,?,?,?,?)", (
        ticker,
        round(float(row["ew_weight"]), 6),
        round(float(row["opt_weight"]), 6),
        round(float(row["tgarch_weight"]), 6),
        round(float(row["weight_diff"]), 6),
    ))
print(f"  optimal_weights    : {len(weights_df)} rows inserted")

conn.commit()
print()
print(f"  Database created   : {DB_PATH}")
print()

# =============================================================================
# SECTION 2 — WINDOW FUNCTIONS: ROLLING BREACH RATES & VAR PREMIUM
# =============================================================================

print("─" * 70)
print("SECTION 2 — SQL Window Functions")
print("─" * 70)

# Rolling 21-day breach rate (SQLite doesn't have native window avg,
# so we do it in pandas after pulling from DB)
daily_df = pd.read_sql("SELECT * FROM daily_risk_metrics ORDER BY date",
                        conn, index_col="date", parse_dates=["date"])

ROLL = 21
daily_df["roll_breach_static"] = daily_df["breach_static"].rolling(ROLL).mean() * 100
daily_df["roll_breach_ewma"]   = daily_df["breach_ewma"].rolling(ROLL).mean()   * 100
daily_df["roll_breach_tgarch"] = daily_df["breach_tgarch"].rolling(ROLL).mean() * 100

# Dynamic VaR premium (T-GARCH vs Static, %)
daily_df["var_premium_pct"] = ((daily_df["var95_tgarch"] - daily_df["var95_static"])
                                / daily_df["var95_static"] * 100)

# Monthly vol regime
daily_df["month"]      = pd.to_datetime(daily_df.index).strftime("%Y-%m")
daily_df["vol_regime"] = daily_df["ewma_vol"].apply(
    lambda v: "HIGH"   if v > 1.2 else
              "MEDIUM" if v > 0.8 else "LOW"
)

# Write enriched table back to DB
daily_df.to_sql("daily_risk_enriched", conn, if_exists="replace", index=True)

print("  Rolling 21-day breach rates computed via pandas (SQLite limitation)")
print()

# SQL QUERIES ──────────────────────────────────────────────────────────────────

print("  ── QUERY 1: Kupiec Backtest Summary ──────────────────────────")
q1 = pd.read_sql("""
    SELECT model, n_breaches,
           ROUND(breach_rate * 100, 1) AS breach_rate_pct,
           ROUND(kupiec_lr, 3)         AS LR_stat,
           ROUND(kupiec_pvalue, 4)     AS p_value,
           pass_fail,
           vol_dynamics
    FROM var_backtest
    ORDER BY kupiec_lr ASC
""", conn)
print(q1.to_string(index=False))
print()

print("  ── QUERY 2: Macro Sensitivity (OLS Coefficients × Shock) ─────")
sens_table = ph4["sensitivity_table"]
sens_df = pd.DataFrame([
    {"Macro Shock": k, "Portfolio Impact (%)": round(v, 3),
     "Direction": "LOSS" if v < 0 else "GAIN"}
    for k, v in sens_table.items()
])
print(sens_df.to_string(index=False))
print()

print("  ── QUERY 3: Stress Scenario Ranking by Severity ──────────────")
q3 = pd.read_sql("""
    SELECT scenario_name, portfolio_pnl,
           pnl_vs_var AS pnl_times_var,
           tlt_contribution, gld_contribution, scenario_type
    FROM stress_scenarios
    ORDER BY portfolio_pnl ASC
""", conn)
print(q3.to_string(index=False))
print()

print("  ── QUERY 4: Liquidity Violation Alerts ───────────────────────")
q4 = pd.read_sql("""
    SELECT ticker, ROUND(position_usd/1e6,4) AS pos_M,
           ROUND(adv_proxy_usd/1e6,2)        AS adv_M,
           pct_of_adv, roll_spread_bps,
           ROUND(stress_exit_cost,0)          AS stress_cost_usd,
           adv_violation
    FROM liquidity_metrics
    ORDER BY adv_violation DESC, pct_of_adv DESC
    LIMIT 5
""", conn)
print(q4.to_string(index=False))
print()

print("  ── QUERY 5: Monthly Vol Regime Summary ───────────────────────")
q5 = pd.read_sql("""
    SELECT month,
           ROUND(AVG(ewma_vol), 3)           AS avg_ewma_vol,
           ROUND(AVG(var95_tgarch)*100, 3)   AS avg_tgarch_var_pct,
           SUM(breach_tgarch)                AS tgarch_breaches,
           MAX(vol_regime)                   AS vol_regime
    FROM daily_risk_enriched
    GROUP BY month
    ORDER BY month
""", conn)
print(q5.to_string(index=False))
print()

print("  ── QUERY 6: Dynamic VaR Premium Statistics ───────────────────")
q6 = pd.read_sql("""
    SELECT
        ROUND(AVG(var_premium_pct), 2)  AS avg_premium_pct,
        ROUND(MAX(var_premium_pct), 2)  AS max_premium_pct,
        ROUND(MIN(var_premium_pct), 2)  AS min_premium_pct,
        SUM(CASE WHEN var_premium_pct > 30 THEN 1 ELSE 0 END) AS days_above_30pct
    FROM daily_risk_enriched
""", conn)
print(q6.to_string(index=False))
print()

