# Commented out IPython magic to ensure Python compatibility.
"""
=============================================================================
PROJECT  — Portfolio Risk, Stress Testing & Macro Scenario Engine
PHASE 8  — Kupiec Walk-Forward Validation
=============================================================================


WHAT THIS PHASE DOES:
  SECTION 1 — Walk-forward setup
              Window 1: Calibrate 2017-2020 → Test 2021
              Window 2: Calibrate 2017-2021 → Test 2022
              Expanding window (add one year each time)
  SECTION 2 — Re-estimate all 4 VaR models on each calibration window
              Static HS, FHS-EWMA, FHS-GARCH, FHS-T-GARCH
  SECTION 3 — Kupiec POF test on each window × model combination
  SECTION 4 — Christoffersen independence test on each combination
  SECTION 5 — Model stability: compare GARCH parameters across windows
  SECTION 6 — Save results
  SECTION 7 — Static visualizations (5 plots)
  SECTION 8 — Interactive visualizations (3 Plotly charts)

RESEARCH ANCHOR:
  Kupiec (1995) — Proportion-of-Failures test
  Christoffersen (1998) — Interval Forecast Evaluation
  Walk-forward validation is the correct methodology for time-series
  backtesting — avoids look-ahead bias in VaR model selection.

HOW TO RUN:
#   %matplotlib inline
  python P1_Phase8_Kupiec_Walkforward.py
=============================================================================
"""

import os, json, warnings
import numpy as np
import pandas as pd
import scipy.stats as stats
import matplotlib.pyplot as plt
import matplotlib.dates as mdates
import matplotlib.ticker as mticker
import plotly.graph_objects as go
from plotly.subplots import make_subplots
from arch import arch_model

warnings.filterwarnings("ignore")
os.makedirs("plots",   exist_ok=True)
os.makedirs("results", exist_ok=True)

# ── Style ─────────────────────────────────────────────────────────────────────
plt.rcParams.update({
    "figure.dpi": 150, "font.family": "DejaVu Sans", "font.size": 10,
    "axes.spines.top": False, "axes.spines.right": False,
    "axes.grid": True, "grid.alpha": 0.22, "grid.linewidth": 0.6,
})
TFS = 13; LFS = 10; AFS = 9
C_STATIC = "#566573"; C_EWMA  = "#2980B9"
C_GARCH  = "#229954"; C_TGARCH= "#C0392B"
C_STEEL  = "#1C2833"; C_GREY  = "#7F8C8D"
C_OK     = "#229954"; C_FAIL  = "#C0392B"; C_WARN  = "#E67E22"

MODEL_COLS = {"Static": C_STATIC, "EWMA": C_EWMA,
              "GARCH":  C_GARCH,  "TGARCH": C_TGARCH}

def clean_ax(ax, xlabel=None, ylabel=None):
    ax.tick_params(labelsize=AFS)
    ax.spines["top"].set_visible(False)
    ax.spines["right"].set_visible(False)
    if xlabel: ax.set_xlabel(xlabel, fontsize=LFS)
    if ylabel: ax.set_ylabel(ylabel, fontsize=LFS)

PTEMPLATE = "plotly_white"
PFONT = dict(family="Arial, sans-serif", size=12, color=C_STEEL)
def playout(title, sub, height=520):
    return dict(
        title=dict(
            text=f"<b>{title}</b><br><sup style='color:#7F8C8D'>{sub}</sup>",
            font=dict(size=15, family="Arial, sans-serif", color=C_STEEL),
            x=0.02, xanchor="left"),
        font=PFONT, template=PTEMPLATE, height=height,
        margin=dict(l=70, r=50, t=90, b=65),
        hovermode="x unified",
        plot_bgcolor="white", paper_bgcolor="white",
    )

# =============================================================================
# 0. LOAD DATA
# =============================================================================

print("=" * 70)
print("PHASE 8 — Kupiec Walk-Forward Validation")
print("=" * 70)
print()

port = pd.read_csv("data/portfolio_daily_returns.csv",
                    index_col=0, parse_dates=True)["portfolio_return"]

with open("data/metadata.json") as f:
    meta = json.load(f)

LAM  = meta["lambda_ewma"]
CONF = 0.95
ALPHA = 1 - CONF

print(f"  Full history : {port.index[0].date()} → {port.index[-1].date()}")
print(f"  VaR confidence: {CONF*100:.0f}%")
print()

# =============================================================================
# SECTION 1 — WALK-FORWARD WINDOWS
# =============================================================================

print("─" * 70)
print("SECTION 1 — Walk-Forward Windows  (Expanding Calibration)")
print("─" * 70)

# Expanding window: calibrate on everything up to year Y, test on year Y+1
WINDOWS = [
    {"label": "W1", "calib_end": "2020-12-31", "test_start": "2021-01-01",
     "test_end": "2021-12-31"},
    {"label": "W2", "calib_end": "2021-12-31", "test_start": "2022-01-01",
     "test_end": "2022-12-31"},
]

for w in WINDOWS:
    calib = port.loc[:w["calib_end"]]
    test  = port.loc[w["test_start"]:w["test_end"]]
    w["n_calib"] = len(calib)
    w["n_test"]  = len(test)
    print(f"  {w['label']}: Calibrate {port.index[0].date()} → {w['calib_end']}  "
          f"({w['n_calib']} days)  |  Test {w['test_start']} → {w['test_end']}  "
          f"({w['n_test']} days)")
print()

# =============================================================================
# SECTION 2 — RE-ESTIMATE ALL VaR MODELS
# =============================================================================

print("─" * 70)
print("SECTION 2 — Re-Estimating VaR Models on Each Window")
print("─" * 70)

def ewma_vol_series(r, lam):
    var = np.zeros(len(r))
    var[0] = r[0]**2
    for t in range(1, len(r)):
        var[t] = lam*var[t-1] + (1-lam)*r[t-1]**2
    return var

def fhs_ewma_var95(r_decimal, lam):
    vs = ewma_vol_series(r_decimal, lam)
    vol = np.where(np.sqrt(vs) < 1e-9, 1e-9, np.sqrt(vs))
    fc  = np.sqrt(lam*vs[-1] + (1-lam)*r_decimal[-1]**2)
    z   = r_decimal / vol
    return float(np.percentile(-z*fc, 95))

def fhs_garch_var95(r_decimal, model_type="garch"):
    r_pct = r_decimal * 100
    o     = 1 if model_type == "tgarch" else 0
    am    = arch_model(r_pct, vol="GARCH", p=1, o=o, q=1, dist="normal")
    res   = am.fit(disp="off", show_warning=False)
    cond_vol = np.array(res.conditional_volatility) / 100
    cond_vol = np.where(cond_vol < 1e-9, 1e-9, cond_vol)
    fc_var  = float(res.forecast(horizon=1).variance.iloc[-1].values[0])
    fc_vol  = np.sqrt(fc_var) / 100
    z       = r_decimal / cond_vol
    v95     = float(np.percentile(-z*fc_vol, 95))
    params  = dict(res.params)
    return v95, params, res.loglikelihood

def rolling_var(port_series, calib_end, test_start, test_end, lam, n_calib):
    """Compute rolling VaR for test period with expanding calib window."""
    test_idx = port_series.loc[test_start:test_end].index
    results  = {m: [] for m in ["static","ewma","garch","tgarch"]}

    calib_r = port_series.loc[:calib_end].values

    # Static VaR: fixed on full calibration window
    static_var = float(np.percentile(-calib_r, 95))

    for date in test_idx:
        ti  = port_series.index.get_loc(date)
        r_w = port_series.values[max(0, ti-n_calib):ti]

        results["static"].append(static_var)
        results["ewma"].append(fhs_ewma_var95(r_w, lam))

        try:
            v_g, _, _ = fhs_garch_var95(r_w, "garch")
        except Exception:
            v_g = results["garch"][-1] if results["garch"] else static_var
        results["garch"].append(v_g)

        try:
            v_t, _, _ = fhs_garch_var95(r_w, "tgarch")
        except Exception:
            v_t = results["tgarch"][-1] if results["tgarch"] else static_var
        results["tgarch"].append(v_t)

    return {m: pd.Series(v, index=test_idx) for m, v in results.items()}

# Estimate models for each window
window_results = []
for w in WINDOWS:
    print(f"  {w['label']}: estimating models  (calibration window = {w['n_calib']} days) …")

    calib_r = port.loc[:w["calib_end"]].values
    test_r  = port.loc[w["test_start"]:w["test_end"]]

    # Full-window parameter estimates (for stability analysis)
    calib_r_pct = calib_r * 100
    _, params_g, ll_g = fhs_garch_var95(calib_r, "garch")
    _, params_t, ll_t = fhs_garch_var95(calib_r, "tgarch")

    print(f"    GARCH(1,1): α={params_g.get('alpha[1]',0):.4f}  "
          f"β={params_g.get('beta[1]',0):.4f}  "
          f"persistence={params_g.get('alpha[1]',0)+params_g.get('beta[1]',0):.4f}")
    print(f"    T-GARCH   : α={params_t.get('alpha[1]',0):.4f}  "
          f"γ={params_t.get('gamma[1]',0):.4f}  "
          f"β={params_t.get('beta[1]',0):.4f}")

    # Rolling VaR estimates for test period
    print(f"    Building rolling VaR for {w['n_test']} test days …")
    var_series = rolling_var(port, w["calib_end"], w["test_start"],
                              w["test_end"], LAM, w["n_calib"])

    w["var_series"] = var_series
    w["test_returns"] = test_r
    w["params_garch"]  = params_g
    w["params_tgarch"] = params_t
    w["ll_g"] = ll_g
    w["ll_t"] = ll_t
    print(f"    Done.\n")

# =============================================================================
# SECTION 3 — KUPIEC POF TEST
# =============================================================================

print("─" * 70)
print("SECTION 3 — Kupiec POF Test  (Each Window × Model)")
print("─" * 70)
print("  H₀: breach rate = 5%   Critical value = 3.84")
print()

def kupiec(n_breach, n_obs, conf=0.95):
    p = 1-conf; x = n_breach; T = n_obs
    p_hat = x/T
    if x==0:   lr = -2*T*np.log(1-p)
    elif x==T: lr = -2*T*np.log(p)
    else:
        lr = -2*(x*np.log(p) + (T-x)*np.log(1-p)
                 - x*np.log(p_hat) - (T-x)*np.log(1-p_hat))
    return round(lr,4), round(1-stats.chi2.cdf(lr,1),6)

kupiec_results = []
model_order = ["static","ewma","garch","tgarch"]
model_labels = {"static":"Static HS-VaR","ewma":"FHS-EWMA",
                "garch":"FHS-GARCH","tgarch":"FHS-T-GARCH"}

print(f"  {'Window':<4s}  {'Model':<16s}  {'N':>5s}  {'Breaches':>8s}  "
      f"{'Rate':>7s}  {'LR':>8s}  {'p':>9s}  Result")
print(f"  {'─'*4}  {'─'*16}  {'─'*5}  {'─'*8}  {'─'*7}  {'─'*8}  {'─'*9}  {'─'*8}")

for w in WINDOWS:
    test_r  = w["test_returns"]
    N       = len(test_r)
    losses  = -test_r

    for model in model_order:
        var_s    = w["var_series"][model]
        breaches = int((losses > var_s).sum())
        br_rate  = breaches / N
        lr, pv   = kupiec(breaches, N)
        passed   = pv > 0.05
        kupiec_results.append({
            "window": w["label"], "model": model_labels[model],
            "test_period": w["test_start"][:4],
            "n_obs": N, "breaches": breaches,
            "breach_rate": round(br_rate, 5),
            "lr_stat": lr, "p_value": pv, "pass": passed,
        })
        print(f"  {w['label']:<4s}  {model_labels[model]:<16s}  {N:>5d}  "
              f"{breaches:>8d}  {br_rate*100:>6.1f}%  {lr:>8.3f}  "
              f"{pv:>9.4f}  {'PASS ✓' if passed else 'FAIL ✗'}")
    print()

kup_df = pd.DataFrame(kupiec_results)

# =============================================================================
# SECTION 4 — CHRISTOFFERSEN INDEPENDENCE TEST
# =============================================================================

print("─" * 70)
print("SECTION 4 — Christoffersen Independence Test")
print("─" * 70)
print("  H₀: breaches are independently distributed (not clustered)")
print()

def christoffersen(breach_series):
    b = breach_series.values.astype(int)
    n00=n01=n10=n11=0
    for i in range(1, len(b)):
        if   b[i-1]==0 and b[i]==0: n00+=1
        elif b[i-1]==0 and b[i]==1: n01+=1
        elif b[i-1]==1 and b[i]==0: n10+=1
        else:                        n11+=1
    tot = n00+n01+n10+n11
    if (n00+n01)==0 or (n10+n11)==0 or tot==0: return np.nan, np.nan
    pi01 = n01/(n00+n01)
    pi11 = n11/(n10+n11) if (n10+n11)>0 else 0
    pi   = (n01+n11)/tot
    if pi in (0,1) or pi01==0 or pi11==0: return np.nan, np.nan
    lr = -2*((n00+n10)*np.log(1-pi)+(n01+n11)*np.log(pi)
             -n00*np.log(1-pi01)-n01*np.log(pi01)
             -n10*np.log(max(1-pi11, 1e-9))
             -n11*np.log(max(pi11, 1e-9)))
    return round(lr,4), round(1-stats.chi2.cdf(lr,1),6)

christ_results = []
print(f"  {'Window':<4s}  {'Model':<16s}  {'LR':>8s}  {'p':>9s}  Independence")
print(f"  {'─'*4}  {'─'*16}  {'─'*8}  {'─'*9}  {'─'*15}")

for w in WINDOWS:
    test_r = w["test_returns"]
    losses = -test_r

    for model in model_order:
        var_s    = w["var_series"][model]
        breach_s = (losses > var_s).astype(int)
        lr_c, pv_c = christoffersen(breach_s)

        if np.isnan(lr_c):
            result = "n/a (insufficient breaches)"
            lr_str = "n/a"; pv_str = "n/a"
        else:
            result = "Independent ✓" if pv_c > 0.05 else "Clustered ✗"
            lr_str = f"{lr_c:.3f}"; pv_str = f"{pv_c:.4f}"

        christ_results.append({
            "window": w["label"], "model": model_labels[model],
            "test_period": w["test_start"][:4],
            "lr_stat": lr_c if not np.isnan(lr_c) else None,
            "p_value": pv_c if not np.isnan(pv_c) else None,
            "independent": (pv_c > 0.05) if not np.isnan(lr_c) else None,
        })
        print(f"  {w['label']:<4s}  {model_labels[model]:<16s}  "
              f"{lr_str:>8s}  {pv_str:>9s}  {result}")
    print()

christ_df = pd.DataFrame(christ_results)

# =============================================================================
# SECTION 5 — MODEL STABILITY ANALYSIS
# =============================================================================

print("─" * 70)
print("SECTION 5 — GARCH Parameter Stability Across Windows")
print("─" * 70)

print(f"  {'Window':<4s}  {'Model':<12s}  {'α':>8s}  {'γ':>8s}  {'β':>8s}  "
      f"{'α+β (pers.)':>12s}  {'Log-Lik':>10s}")
print(f"  {'─'*4}  {'─'*12}  {'─'*8}  {'─'*8}  {'─'*8}  {'─'*12}  {'─'*10}")

stability_rows = []
for w in WINDOWS:
    pg = w["params_garch"]
    pt = w["params_tgarch"]

    a_g = pg.get("alpha[1]", 0); b_g = pg.get("beta[1]", 0)
    a_t = pt.get("alpha[1]", 0); g_t = pt.get("gamma[1]", 0); b_t = pt.get("beta[1]", 0)

    print(f"  {w['label']:<4s}  {'GARCH(1,1)':<12s}  {a_g:>8.4f}  {'—':>8s}  "
          f"{b_g:>8.4f}  {a_g+b_g:>12.4f}  {w['ll_g']:>10.2f}")
    print(f"  {w['label']:<4s}  {'T-GARCH':<12s}  {a_t:>8.4f}  {g_t:>8.4f}  "
          f"{b_t:>8.4f}  {a_t+0.5*g_t+b_t:>12.4f}  {w['ll_t']:>10.2f}")

    stability_rows.append({
        "window": w["label"], "model": "GARCH",
        "alpha": a_g, "gamma": None, "beta": b_g,
        "persistence": a_g+b_g, "loglik": w["ll_g"]
    })
    stability_rows.append({
        "window": w["label"], "model": "T-GARCH",
        "alpha": a_t, "gamma": g_t, "beta": b_t,
        "persistence": a_t+0.5*g_t+b_t, "loglik": w["ll_t"]
    })
    print()

stability_df = pd.DataFrame(stability_rows)

# LR test for T-GARCH vs GARCH in each window
print("  Likelihood Ratio test (T-GARCH vs GARCH):")
for w in WINDOWS:
    lr_stat = 2 * (w["ll_t"] - w["ll_g"])
    lr_pval = 1 - stats.chi2.cdf(lr_stat, df=1)
    print(f"  {w['label']}: LR={lr_stat:.3f}, p={lr_pval:.4f}  "
          f"→ γ {'significant — T-GARCH preferred' if lr_pval<0.05 else 'not significant'}")
print()

# =============================================================================
# SECTION 6 — SAVE RESULTS
# =============================================================================

print("─" * 70)
print("SECTION 6 — Saving Results")
print("─" * 70)

kup_df.to_csv("results/phase8_kupiec_walkforward.csv", index=False)
christ_df.to_csv("results/phase8_christoffersen_walkforward.csv", index=False)
stability_df.to_csv("results/phase8_garch_stability.csv", index=False)

print("  Saved → results/phase8_kupiec_walkforward.csv")
print("  Saved → results/phase8_christoffersen_walkforward.csv")
print("  Saved → results/phase8_garch_stability.csv")
print()

# =============================================================================
# SECTION 7 — STATIC VISUALIZATIONS
# =============================================================================

print("─" * 70)
print("SECTION 7 — Static Visualizations")
print("─" * 70)

# ── PLOT 01: Kupiec Results — Both Windows ─────────────────────────────────────
fig, axes = plt.subplots(1, 2, figsize=(16, 6))
fig.subplots_adjust(wspace=0.32)

for ax_i, w_label in enumerate(["W1","W2"]):
    ax   = axes[ax_i]
    wdat = kup_df[kup_df["window"] == w_label]
    year = wdat["test_period"].iloc[0]

    bar_cols = [C_OK if r else C_FAIL for r in wdat["pass"]]
    bars = ax.bar(range(len(wdat)), wdat["breach_rate"]*100,
                  color=bar_cols, edgecolor="white", width=0.55, zorder=3)
    ax.axhline(5.0, color=C_STEEL, lw=1.5, ls="--", label="Expected 5%")
    ax.axhline(6.5, color=C_WARN,  lw=1.0, ls=":", alpha=0.8,
               label="Informal fail (6.5%)")
    for bar, rate in zip(bars, wdat["breach_rate"]*100):
        ax.text(bar.get_x()+bar.get_width()/2, rate+0.1,
                f"{rate:.1f}%", ha="center", va="bottom",
                fontsize=9.5, fontweight="bold", color=C_STEEL)

    ax.set_xticks(range(len(wdat)))
    ax.set_xticklabels(["Static\nHS-VaR","FHS-\nEWMA","FHS-\nGARCH","FHS-\nT-GARCH"],
                       fontsize=9)
    ax.set_title(f"{w_label}: Test Year {year}\n"
                 f"Calibration: 2017 → {WINDOWS[ax_i]['calib_end'][:4]} (expanding)",
                 fontsize=11, fontweight="bold")
    clean_ax(ax, ylabel="Breach Rate (%)")
    ax.yaxis.grid(True, alpha=0.22); ax.set_axisbelow(True)
    ax.legend(fontsize=8, framealpha=0.92)

fig.suptitle("Plot 01 — Kupiec Walk-Forward: Breach Rate by Window & Model\n"
             "Green = PASS (≤6.5%)  ·  Red = FAIL",
             fontsize=TFS, fontweight="bold")
plt.savefig("plots/phase8_01_kupiec_walkforward.png", dpi=150, bbox_inches="tight")
plt.show(); plt.close()

# ── PLOT 02: Kupiec LR Statistic — Both Windows ────────────────────────────────
fig, axes = plt.subplots(1, 2, figsize=(16, 5))
fig.subplots_adjust(wspace=0.32)

for ax_i, w_label in enumerate(["W1","W2"]):
    ax   = axes[ax_i]
    wdat = kup_df[kup_df["window"] == w_label]
    year = wdat["test_period"].iloc[0]

    bar_cols = [C_OK if r else C_FAIL for r in wdat["pass"]]
    bars = ax.bar(range(len(wdat)), wdat["lr_stat"],
                  color=bar_cols, edgecolor="white", width=0.55, zorder=3)
    ax.axhline(3.84, color=C_STEEL, lw=1.8, ls="--",
               label="Critical = 3.84  (χ²(1), 5%)")
    for bar, lr, pv in zip(bars, wdat["lr_stat"], wdat["p_value"]):
        ax.text(bar.get_x()+bar.get_width()/2, lr+0.05,
                f"LR={lr:.2f}\np={pv:.3f}", ha="center", va="bottom",
                fontsize=8, color=C_STEEL, linespacing=1.4)

    ax.set_xticks(range(len(wdat)))
    ax.set_xticklabels(["Static","EWMA","GARCH","T-GARCH"], fontsize=9)
    ax.set_title(f"{w_label}: Test {year}  (LR stat)", fontsize=11, fontweight="bold")
    clean_ax(ax, ylabel="Kupiec LR Statistic")
    ax.yaxis.grid(True, alpha=0.22); ax.set_axisbelow(True)
    ax.legend(fontsize=8, framealpha=0.92)

fig.suptitle("Plot 02 — Kupiec LR Statistic: Walk-Forward Results\n"
             "Lower LR = better calibrated · Green < 3.84 = PASS",
             fontsize=TFS, fontweight="bold")
plt.savefig("plots/phase8_02_kupiec_lr.png", dpi=150, bbox_inches="tight")
plt.show(); plt.close()

# ── PLOT 03: VaR Breach Scatter — Both Windows ────────────────────────────────
fig, axes = plt.subplots(1, 2, figsize=(16, 5))
fig.subplots_adjust(wspace=0.28)

for ax_i, w in enumerate(WINDOWS):
    ax = axes[ax_i]
    test_r = w["test_returns"]
    losses = -test_r

    ax.fill_between(test_r.index, 0, losses.values*100,
                    alpha=0.25, color="#AEB6BF", label="Actual daily loss")

    for model, col, dash in [
        ("static",  C_STATIC, "--"),
        ("tgarch",  C_TGARCH, "-"),
    ]:
        var_s   = w["var_series"][model]
        breach  = (losses > var_s)
        ax.plot(var_s.index, var_s.values*100,
                color=col, lw=1.5, ls=dash,
                label=f"{model_labels[model]}")
        b_dates = breach[breach].index
        if len(b_dates):
            ax.scatter(b_dates, losses.loc[b_dates]*100,
                       color=col, marker="x", s=50, zorder=5)

    ax.set_title(f"{w['label']}: Test {w['test_start'][:4]}  "
                 f"(Static breaches vs T-GARCH breaches)",
                 fontsize=10, fontweight="bold")
    clean_ax(ax, "Date", "Daily Loss / VaR (%)")
    ax.xaxis.set_major_formatter(mdates.DateFormatter("%b"))
    ax.xaxis.set_major_locator(mdates.MonthLocator())
    ax.legend(fontsize=8, framealpha=0.92)

fig.suptitle("Plot 03 — Walk-Forward: Daily Loss vs VaR Thresholds  ·  × markers = breaches  ·  Static vs T-GARCH across both test years",
             fontsize=11, fontweight="bold", y=1.06)
plt.savefig("plots/phase8_03_var_breach_scatter.png", dpi=150, bbox_inches="tight")
plt.show(); plt.close()

# ── PLOT 04: GARCH Parameter Stability ────────────────────────────────────────
fig, axes = plt.subplots(1, 3, figsize=(15, 5))
fig.subplots_adjust(wspace=0.35)

params_to_plot = [
    ("alpha", "α (ARCH term)", axes[0]),
    ("beta",  "β (GARCH term)", axes[1]),
    ("persistence", "Persistence (α+β or α+0.5γ+β)", axes[2]),
]
w_labels = ["W1\n(calib→2020)", "W2\n(calib→2021)"]

for param, ylabel, ax in params_to_plot:
    for model, col, marker in [("GARCH", C_GARCH, "o"), ("T-GARCH", C_TGARCH, "s")]:
        vals = stability_df[stability_df["model"]==model][param].tolist()
        if param == "gamma" and model == "GARCH":
            continue
        ax.plot(range(len(w_labels)), vals, color=col, lw=2.0,
                marker=marker, ms=8, label=model)
        for i, v in enumerate(vals):
            ax.text(i, v+0.003, f"{v:.4f}", ha="center", va="bottom",
                    fontsize=8, color=col)
    ax.set_xticks(range(len(w_labels)))
    ax.set_xticklabels(w_labels, fontsize=9)
    ax.set_title(ylabel, fontsize=10, fontweight="bold")
    clean_ax(ax)
    ax.legend(fontsize=8, framealpha=0.92)
    ax.yaxis.grid(True, alpha=0.22); ax.set_axisbelow(True)
    if param == "persistence":
        ax.axhline(1.0, color=C_STEEL, lw=1.0, ls="--",
                   alpha=0.7, label="Unit root")

fig.suptitle("Plot 04 — GARCH Parameter Stability Across Walk-Forward Windows\n"
             "Stable parameters → model structure holds across regimes",
             fontsize=TFS, fontweight="bold")
plt.savefig("plots/phase8_04_garch_stability.png", dpi=150, bbox_inches="tight")
plt.show(); plt.close()

# ── PLOT 05: Walk-Forward Summary Table ───────────────────────────────────────
fig = plt.figure(figsize=(18, 6.0))
title_ax = fig.add_axes([0, 0.85, 1, 0.15])
title_ax.axis("off")
title_ax.text(0.5, 0.65,
    "Plot 05 — Walk-Forward Validation Summary: Kupiec + Christoffersen",
    ha="center", va="center", fontsize=TFS, fontweight="bold", color=C_STEEL,
    transform=title_ax.transAxes)
title_ax.text(0.5, 0.15,
    "Two expanding windows · 4 models · Both POF and independence tests",
    ha="center", va="center", fontsize=9, color=C_GREY, style="italic",
    transform=title_ax.transAxes)

ax = fig.add_axes([0.01, 0.02, 0.98, 0.82])
ax.axis("off")

hdr = ["Window","Test Year","Model","Breaches","Breach Rate","LR Stat","p-value","POF","Independence"]
rows_tbl = []
for _, row in kup_df.iterrows():
    # Find christoffersen result
    c_row = christ_df[
        (christ_df["window"]==row["window"]) &
        (christ_df["model"]==row["model"])
    ]
    if len(c_row) and c_row.iloc[0]["independent"] is not None:
        ind = "✓ Indep" if c_row.iloc[0]["independent"] else "✗ Clust"
    else:
        ind = "n/a"

    rows_tbl.append([
        row["window"], row["test_period"], row["model"],
        str(row["breaches"]),
        f"{row['breach_rate']*100:.1f}%",
        f"{row['lr_stat']:.3f}",
        f"{row['p_value']:.4f}",
        "PASS ✓" if row["pass"] else "FAIL ✗",
        ind,
    ])

tbl = ax.table(cellText=rows_tbl, colLabels=hdr, loc="center", cellLoc="center")
tbl.auto_set_font_size(False); tbl.set_fontsize(8.5); tbl.scale(1, 2.0)
tbl.auto_set_column_width(col=list(range(len(hdr))))

for j in range(len(hdr)):
    tbl[0, j].set_facecolor(C_STEEL)
    tbl[0, j].set_text_props(color="white", fontweight="bold")

for i, row_data in enumerate(rows_tbl, start=1):
    pof_pass = "PASS" in row_data[7]
    bg = "#EAFAF1" if pof_pass else "#FDEDEC"
    for j in range(len(hdr)):
        tbl[i, j].set_facecolor(bg)
    tbl[i, 7].set_text_props(
        color=C_OK if pof_pass else C_FAIL, fontweight="bold"
    )

plt.savefig("plots/phase8_05_walkforward_summary.png", dpi=150, bbox_inches="tight")
plt.show(); plt.close()

print("  All 5 static plots displayed and saved.\n")

# =============================================================================
# SECTION 8 — INTERACTIVE VISUALIZATIONS
# =============================================================================

print("─" * 70)
print("SECTION 8 — Interactive Visualizations (Plotly)")
print("─" * 70)

# ── I1: Breach Rate Heatmap across windows × models ──────────────────────────
print("  Rendering I1 — Breach Rate Heatmap …")
pivot = kup_df.pivot(index="model", columns="test_period", values="breach_rate") * 100
pass_pivot = kup_df.pivot(index="model", columns="test_period", values="pass")

# Color = deviation from 5% target: green=on-target, red=far from target
deviation = np.abs(pivot.values - 5.0)   # 0 = perfect, large = bad

fig_i1 = go.Figure(data=go.Heatmap(
    z=deviation,
    x=pivot.columns.tolist(),
    y=pivot.index.tolist(),
    colorscale=[[0,"#EAFAF1"],[0.4,"#F9E79F"],[1.0,"#FADBD8"]],
    zmin=0, zmax=5,
    text=pivot.values.round(1),
    texttemplate="%{text:.1f}%",
    textfont=dict(size=13, color="#1C2833", family="Arial Black"),
    colorbar=dict(title="Deviation<br>from 5%<br>target (pp)",
                  thickness=14,
                  tickvals=[0,2.5,5],
                  ticktext=["0 (on target)","2.5pp","5pp+"])
))

layout_i1 = playout("I1 — Walk-Forward Breach Rates: Model × Test Year",
                    "Green = PASS (≤6.5%) · Yellow = borderline · Red = FAIL · Target = 5%",
                    height=420)
layout_i1["margin"] = dict(l=160, r=80, t=100, b=70)
fig_i1.update_layout(
    **layout_i1,
    xaxis=dict(title="Test Year", tickfont=dict(size=13)),
    yaxis=dict(title="Model", tickfont=dict(size=11)),
)
fig_i1.show()

# ── I2: VaR paths — both windows, T-GARCH vs Static ─────────────────────────
print("  Rendering I2 — Walk-Forward VaR Paths …")
fig_i2 = make_subplots(rows=1, cols=2,
                        subplot_titles=[f"Test {WINDOWS[i]['test_start'][:4]}"
                                        for i in range(2)],
                        horizontal_spacing=0.08)

for col_i, w in enumerate(WINDOWS, start=1):
    test_r = w["test_returns"]
    losses = -test_r

    fig_i2.add_trace(go.Bar(
        x=test_r.index, y=(losses.values*100).round(3),
        name=f"Loss {w['test_start'][:4]}",
        marker_color="#AED6F1", opacity=0.65,
        showlegend=(col_i==1),
        hovertemplate="<b>%{x|%b %d}</b> Loss: %{y:.3f}%<extra></extra>"
    ), row=1, col=col_i)

    for model, col, dash, nm in [
        ("static", C_STATIC, "dash",  "Static VaR"),
        ("tgarch",  C_TGARCH, "solid", "T-GARCH VaR"),
    ]:
        fig_i2.add_trace(go.Scatter(
            x=w["var_series"][model].index,
            y=(w["var_series"][model].values*100).round(3),
            mode="lines", name=nm,
            line=dict(color=col, width=1.8, dash=dash),
            showlegend=(col_i==1),
            hovertemplate=f"<b>{nm}</b>: %{{y:.3f}}%<extra></extra>"
        ), row=1, col=col_i)

layout_i2 = playout("I2 — Walk-Forward VaR: Static vs T-GARCH  (Both Test Windows)",
                     "Hover for daily VaR values · T-GARCH adapts to vol regime changes",
                     height=520)
layout_i2.pop("hovermode", None)
fig_i2.update_layout(**layout_i2, hovermode="x unified",
                      legend=dict(x=0.01, y=0.99, font=dict(size=11),
                                  bgcolor="rgba(255,255,255,0.92)"))
fig_i2.update_yaxes(title_text="Daily Loss / VaR (%)")
fig_i2.show()

# ── I3: Kupiec LR comparison — model performance across windows ───────────────
print("  Rendering I3 — Kupiec LR Walk-Forward Comparison …")
# Use subplots: top = Static (high LR), bottom = dynamic models (low LR)
fig_i3 = make_subplots(rows=2, cols=1,
                        subplot_titles=("Static HS-VaR (fails both years)",
                                        "Dynamic Models (all pass — zoom in)"),
                        vertical_spacing=0.14, row_heights=[0.45, 0.55])

# Static on top panel
sub_s = kup_df[kup_df["model"]=="Static HS-VaR"]
fig_i3.add_trace(go.Scatter(
    x=sub_s["test_period"].tolist(), y=sub_s["lr_stat"].tolist(),
    mode="lines+markers+text", name="Static HS-VaR",
    line=dict(color=C_STATIC, width=2.5),
    marker=dict(size=12, color=C_STATIC),
    text=[f"LR={v:.2f}" for v in sub_s["lr_stat"]],
    textposition="top center", textfont=dict(size=11, color=C_STATIC),
    hovertemplate="<b>Static</b><br>Year: %{x}<br>LR: %{y:.3f}<extra></extra>"
), row=1, col=1)
fig_i3.add_hline(y=3.84, line_dash="dash", line_color=C_STEEL,
                  line_width=1.5, row=1, col=1,
                  annotation_text="Critical 3.84", annotation_font=dict(size=10))

# Dynamic models on bottom panel
for model_name, col in [
    ("FHS-EWMA", C_EWMA), ("FHS-GARCH", C_GARCH), ("FHS-T-GARCH", C_TGARCH)
]:
    sub = kup_df[kup_df["model"]==model_name]
    fig_i3.add_trace(go.Scatter(
        x=sub["test_period"].tolist(), y=sub["lr_stat"].tolist(),
        mode="lines+markers+text", name=model_name,
        line=dict(color=col, width=2.2),
        marker=dict(size=10, color=col),
        text=[f"{v:.2f}" for v in sub["lr_stat"]],
        textposition="top center", textfont=dict(size=10, color=col),
        hovertemplate=f"<b>{model_name}</b><br>Year: %{{x}}<br>LR: %{{y:.3f}}<extra></extra>"
    ), row=2, col=1)
fig_i3.add_hline(y=3.84, line_dash="dash", line_color=C_STEEL,
                  line_width=1.5, row=2, col=1,
                  annotation_text="Critical 3.84", annotation_font=dict(size=10))

layout_i3 = playout("I3 — Walk-Forward Kupiec LR: Static vs Dynamic Models",
                     "Static fails both years · All dynamic models stay well below 3.84",
                     height=580)
layout_i3.pop("hovermode", None)
fig_i3.update_layout(**layout_i3, hovermode="x unified",
                      legend=dict(x=0.01, y=0.99, font=dict(size=11),
                                  bgcolor="rgba(255,255,255,0.92)", bordercolor="#cccccc"))
fig_i3.update_yaxes(title_text="Kupiec LR", row=1, col=1)
fig_i3.update_yaxes(title_text="Kupiec LR", row=2, col=1)
fig_i3.update_xaxes(title_text="Test Year", row=2, col=1)
fig_i3.show()

print("  All 3 interactive charts displayed.\n")

